(window.__DS = window.__DS || {})["gineco"] = {"sections": [{"title": "1. Anamnese — o que ela antecipa dos spoilers", "sub": "Aula 1 · Anamnese e exame físico", "blocks": [{"t": "ul", "v": ["Queixas mais frequentes: <b>sangramento, dor pélvica e corrimento</b>.", "Ciclo normal (slide): intervalo de <b>24 a 35 dias</b>, fluxo de <b>3 a 7 dias</b>, <b>30 a 80 mL</b>.", "<b>Sangramento pós-menopausa sempre se investiga</b> (endométrio: câncer, atrofia, TH, trauma, hiperplasia, <b>tamoxifeno</b>). 1º exame: USG transvaginal.", "<b>Beta-hCG</b> em toda amenorreia, dor pélvica ou sangramento na idade reprodutiva.", "<b>Dor à mobilização do colo</b> = pista clássica de DIP. Dismenorreia progressiva + dispareunia profunda = endometriose.", "Curetagem + amenorreia → <b>Asherman</b>. Hemorragia pós-parto + amenorreia + sem lactação → <b>Sheehan</b>.", "Leiomioma é <b>4 a 5 vezes mais comum na mulher negra</b>.", "Exame das mamas: inspeção estática → dinâmica → palpação axilar e supraclavicular → palpação mamária → expressão aréolo-papilar."]}, {"t": "q", "v": [{"q": "Quais são os parâmetros do ciclo menstrual normal no slide?", "a": "Intervalo de 24 a 35 dias, fluxo de 3 a 7 dias, volume de 30 a 80 mL.", "id": "1-anamnese-01"}, {"q": "Qual o primeiro exame diante de sangramento na pós-menopausa?", "a": "USG transvaginal (avaliar o endométrio); depois histeroscopia com biópsia se indicado.", "id": "1-anamnese-02"}, {"q": "Qual medicamento obriga a investigar sangramento como possível doença endometrial?", "a": "Tamoxifeno.", "id": "1-anamnese-03"}, {"q": "Qual exame é obrigatório em toda dor pélvica na idade reprodutiva?", "a": "Beta-hCG.", "id": "1-anamnese-04"}]}], "id": "1-anamnese"}, {"title": "2. Vulvovaginites: vaginose, tricomoníase e candidíase", "sub": "Aula 2 · Corrimentos vaginais (Prof. Ricardo Campello)", "blocks": [{"t": "h2", "v": "Conteúdo vaginal normal"}, {"t": "ul", "v": ["Flora: <b>lactobacilos ~90%</b>; outras bactérias ~10% (<i>S. epidermidis</i>, <i>Streptococcus</i>, <i>Gardnerella</i>, <i>E. coli</i>, anaeróbios).", "<b>pH: 3,5 a 4,5 na menacme</b>; <b>5 a 7 na pré-púbere e na pós-menopausa</b>.", "Alcalinizam o pH: muco cervical, <b>sêmen</b>, sangue menstrual, duchas e antibióticos, IST, gravidez e menopausa.", "Corrimento fisiológico: muco, transudato, células descamadas, secreção de Bartholin e Skene; a fresco mostra lactobacilos e poucos leucócitos."]}, {"t": "q", "v": [{"q": "Qual o pH vaginal normal na menacme e na pós-menopausa (slide)?", "a": "Menacme: 3,5 a 4,5. Pré-púbere e pós-menopausa: 5 a 7.", "id": "2-vulvovaginites-vaginose-tr-01"}, {"q": "Cite 4 fatores que alcalinizam o pH vaginal.", "a": "Sêmen, sangue menstrual, muco cervical, duchas/antibióticos, IST, gravidez/menopausa.", "id": "2-vulvovaginites-vaginose-tr-02"}, {"q": "PEGADINHA: pós-menopausa assintomática com pH 6 tem vaginose?", "a": "Não. pH 5 a 7 é normal nessa fase; pH isolado não fecha VB.", "id": "2-vulvovaginites-vaginose-tr-03"}]}, {"t": "h2", "v": "Vaginose bacteriana (VB)"}, {"t": "ul", "v": ["<b>Causa mais comum de corrimento: 40 a 50%</b>; <b>3× mais comum em negras</b>.", "Agente: <b>polimicrobiano</b> — queda de lactobacilos e aumento de 100 a 1.000× de anaeróbios: <i>Gardnerella vaginalis</i>, <i>Mobiluncus</i>, <i>Bacteroides</i>, <i>Mycoplasma hominis</i>, <i>Ureaplasma</i>, <i>Peptostreptococcus</i>, <i>Prevotella</i>.", "<b>Mecanismo do odor:</b> aminas (putrescina, cadaverina, trimetilamina) <b>volatilizam com pH elevado</b> → odor de peixe, pior após coito sem preservativo (sêmen alcalino) e na menstruação.", "<b>Sem inflamação e sem leucócitos</b>: é vaginose, não vaginite.", "Fatores de risco: múltiplos parceiros e ducha vaginal. <b>Protegem: preservativo e contraceptivo hormonal combinado.</b>"]}, {"t": "p", "v": "<b>Clínica:</b> corrimento <b>fino, branco ou acinzentado</b>, odor de pescado, prurido pouco ou ausente; muitas assintomáticas. <b>Exame especular sem sinais inflamatórios.</b> Parceiro sem quadro."}, {"t": "p", "v": "<b>Diagnóstico (slide, 4 elementos):</b> clínica + <b>pH &gt; 4,5</b> + <b>teste das aminas positivo (2 gotas de KOH 10%)</b> + <b>clue cells ≥ 20%</b> das células epiteliais. <cx>[Complemento]</cx> Critérios de Amsel = 3 de 4; padrão-ouro em pesquisa = escore de Nugent (Gram)."}, {"t": "p", "v": "<b>Complicações na gestação:</b> rotura prematura de membranas (<b>~7,3×</b>), trabalho de parto e parto prematuros, endometrite pós-cesárea."}, {"t": "p", "v": "<b>Tratamento:</b> tratar <b>toda sintomática</b>; <b>não tratar o parceiro</b> de rotina; recorrência ~20%."}, {"t": "table", "head": ["Situação", "Esquema (tabela CDC 2006 do slide)", "No slide"], "rows": [["Não gestante", "<b>Metronidazol 500 mg VO 12/12 h por 7 dias</b>", "Recomendado"], ["Não gestante", "Metronidazol gel 0,75%, 5 g intravaginal à noite por 5 dias", "Recomendado"], ["Não gestante", "Clindamicina creme 2%, 5 g à noite por 7 dias", "Recomendado"], ["Não gestante", "Metronidazol 2 g dose única; clindamicina 300 mg VO 12/12 h 7 dias", "Alternativo"], ["<b>Gestante</b>", "<b>Metronidazol 250 mg VO 8/8 h (3×/dia) por 7 dias</b> ou clindamicina 300 mg 12/12 h 7 dias", "Recomendado"]]}, {"t": "div", "v": "tabela de 2006. Hoje o metronidazol 2 g dose única saiu (menor eficácia), tinidazol e secnidazol são aceitos (CDC 2021), e a gestante pode usar 500 mg 12/12 h por 7 dias. Na prova, escreva o do slide."}, {"t": "q", "v": [{"q": "Qual a causa mais comum de corrimento e qual a frequência?", "a": "Vaginose bacteriana: 40 a 50% dos corrimentos.", "id": "2-vulvovaginites-vaginose-tr-04"}, {"q": "A VB é mais comum em qual grupo?", "a": "Mulheres negras (3×).", "id": "2-vulvovaginites-vaginose-tr-05"}, {"q": "Por que se chama vaginose e não vaginite?", "a": "Não há inflamação nem leucócitos; é disbiose.", "id": "2-vulvovaginites-vaginose-tr-06"}, {"q": "Explique o odor de peixe e por que piora após o coito.", "a": "Anaeróbios produzem aminas que volatilizam em pH alto; o sêmen é alcalino.", "id": "2-vulvovaginites-vaginose-tr-07"}, {"q": "Cite os 4 elementos diagnósticos do slide.", "a": "Clínica, pH &gt; 4,5, teste das aminas positivo (KOH 10%), clue cells ≥ 20%.", "id": "2-vulvovaginites-vaginose-tr-08"}, {"q": "Fatores de risco e de proteção da VB?", "a": "Risco: múltiplos parceiros e ducha. Proteção: preservativo e ACO combinado.", "id": "2-vulvovaginites-vaginose-tr-09"}, {"q": "Tratamento da VB na não gestante?", "a": "Metronidazol 500 mg VO 12/12 h por 7 dias (ou gel 0,75% 5 noites, ou clindamicina creme 7 noites).", "id": "2-vulvovaginites-vaginose-tr-10"}, {"q": "Tratamento da VB na gestante segundo o slide?", "a": "Metronidazol 250 mg VO 8/8 h por 7 dias (ou clindamicina 300 mg 12/12 h 7 dias).", "id": "2-vulvovaginites-vaginose-tr-11"}, {"q": "Complicações da VB na gestação?", "a": "Rotura prematura de membranas (~7,3×), parto prematuro, endometrite pós-cesárea.", "id": "2-vulvovaginites-vaginose-tr-12"}, {"q": "Trata o parceiro na VB?", "a": "Não, de rotina.", "id": "2-vulvovaginites-vaginose-tr-13"}]}, {"t": "h2", "v": "Tricomoníase"}, {"t": "ul", "v": ["<i>Trichomonas vaginalis</i>: <b>protozoário flagelado, maior que o leucócito</b>, citotóxico; afinidade pelo epitélio vaginal e trato urinário com <b>pH acima de 6</b>.", "<b>Transmissão exclusivamente sexual (IST)</b>; 10 a 25% das infecções vaginais. Associa-se à <b>gonorreia</b>.", "Fatores de risco: múltiplos parceiros, baixo nível socioeconômico, raça negra, tabagismo, IST prévia, não usar preservativo.", "Complicações: infecção pós-aborto, endometrite puerperal, parto prematuro, rotura prematura de membranas."]}, {"t": "p", "v": "<b>Clínica:</b> corrimento <b>espumoso, amarelo-esverdeado</b>, odor fétido; prurido, <b>disúria, dispareunia</b>, irritação vulvar, dor em baixo ventre. <b>Exame:</b> colpite focal ou difusa, cervicite, <b>colo em morango</b>. Homem geralmente assintomático."}, {"t": "p", "v": "<b>Diagnóstico:</b> clínica + <b>pH &gt; 6</b> + <b>protozoário móvel no exame a fresco</b> (muitos leucócitos <cx>[Complemento]</cx>). <cx>[Complemento]</cx> Colo em morango é específico, mas pouco sensível a olho nu; há cultura e testes moleculares."}, {"t": "p", "v": "<b>Tratamento:</b> metronidazol <b>2 g VO dose única (homem)</b> ou <b>500 mg VO 12/12 h por 7 dias (mulher)</b>. <b>Tratar o parceiro.</b> Gel tópico só alivia sintomas. Gestante: tratar <b>a partir do 3º mês</b>."}, {"t": "div", "v": "o CDC atual recomenda tratar a gestante sintomática em qualquer idade gestacional. Na prova, escreva \"a partir do 3º mês\" (slide)."}, {"t": "q", "v": [{"q": "Qual o agente da tricomoníase e como se transmite?", "a": "<i>Trichomonas vaginalis</i>, protozoário flagelado; transmissão exclusivamente sexual.", "id": "2-vulvovaginites-vaginose-tr-14"}, {"q": "Qual pH o tricomonas prefere / qual o pH do slide para o diagnóstico?", "a": "Acima de 6.", "id": "2-vulvovaginites-vaginose-tr-15"}, {"q": "Descreva o corrimento e o sinal clássico ao especular.", "a": "Espumoso, amarelo-esverdeado, fétido; colo em morango (colpite focal/difusa).", "id": "2-vulvovaginites-vaginose-tr-16"}, {"q": "Com qual IST a tricomoníase se associa?", "a": "Gonorreia.", "id": "2-vulvovaginites-vaginose-tr-17"}, {"q": "Como se confirma no consultório?", "a": "Exame a fresco mostrando protozoário móvel (com muitos leucócitos).", "id": "2-vulvovaginites-vaginose-tr-18"}, {"q": "Esquema do slide para homem e para mulher?", "a": "Homem: metronidazol 2 g dose única. Mulher: 500 mg 12/12 h por 7 dias.", "id": "2-vulvovaginites-vaginose-tr-19"}, {"q": "Trata o parceiro? E o gel?", "a": "Sim, sempre. O gel de metronidazol só alivia sintomas.", "id": "2-vulvovaginites-vaginose-tr-20"}, {"q": "Quando tratar a gestante, segundo o slide?", "a": "A partir do terceiro mês.", "id": "2-vulvovaginites-vaginose-tr-21"}]}, {"t": "h2", "v": "Candidíase vulvovaginal (CVV)"}, {"t": "ul", "v": ["<i>Candida albicans</i>: <b>comensal em 20 a 50%</b> das mulheres saudáveis (presença isolada não é doença). Recorrentes: pensar em <i>C. glabrata</i>.", "<b>Dimórfica:</b> levedura = colonização (assintomática, transmissível); <b>pseudo-hifa = forma invasiva</b> (infecção). Reprodução por brotamento.", "Fisiopatologia: contato → penetração → <b>terreno favorável</b> (queda das defesas: mucosa íntegra, flora, PMN, monócitos, IgA, IgG, estrogênio, imunidade celular).", "Perpetuam o fungo: antibiótico recente, dieta com açúcar, tratamento deficitário, sem abstinência no tratamento, <b>não tratar parceiro na recidiva</b>, álcool no tratamento, ACO, DM, gravidez, imunossupressão, roupas justas/sintéticas, desodorante íntimo, lavagem inadequada da roupa íntima."]}, {"t": "p", "v": "<b>Clínica:</b> <b>prurido que piora com o calor</b>, corrimento <b>branco em \"leite talhado\"</b>, <b>sem odor</b>, ardor vulvar, dispareunia, disúria. Exame: vulvovaginite com eritema; parceiro pode ter balanite."}, {"t": "p", "v": "<b>Diagnóstico:</b> clínica + exame a fresco com <b>KOH 10% → pseudo-hifas</b>. pH normal (&lt; 4,5) <cx>[Complemento]</cx>. Recorrente: <b>cultura</b>."}, {"t": "p", "v": "<b>Tratamento (não complicada):</b> <b>fluconazol 150 mg VO dose única</b> (recomendado) ou azólico tópico (clotrimazol creme 1% 6 dias ou cp vaginal 500 mg dose única; miconazol creme 2% 7 dias; tioconazol dose única; nistatina 14 dias). Itraconazol e cetoconazol: \"não recomendados\" no slide. Medidas gerais: evitar roupa apertada/sintética, duchas e açúcar; reduzir estresse. <cx>[Complemento]</cx> Gestante: só azólico tópico."}, {"t": "h2", "v": "Candidíase vulvovaginal recorrente (CVVR)"}, {"t": "ul", "v": ["<b>≥ 4 episódios documentados por ano</b>; ~5% das mulheres (10 a 20% não <i>albicans</i>).", "Perfil: ~30 anos, nuligesta, escolaridade alta, <b>higiene exagerada</b>, piora no verão/praia, estresse, atopia e rinite alérgica. Mecanismo: depressão de linfócitos locais.", "Conduta: <b>confirmar com cultura</b> → <b>14 dias de tópico</b> → manutenção com <b>fluconazol 150 mg/semana</b> (ou no 1º dia do ciclo) <b>por 6 meses</b>. Atenção à hepatotoxicidade.", "<b>Parceiro: só se balanite ou dermatite peniana.</b>"]}, {"t": "q", "v": [{"q": "Por que achar Candida no exame não significa doença?", "a": "Ela é comensal em 20 a 50% das mulheres saudáveis.", "id": "2-vulvovaginites-vaginose-tr-22"}, {"q": "Qual forma da Candida coloniza e qual causa infecção?", "a": "Levedura coloniza; pseudo-hifa é a forma invasiva.", "id": "2-vulvovaginites-vaginose-tr-23"}, {"q": "Cite 5 condições que perpetuam a candidíase.", "a": "Antibiótico, DM, gravidez, ACO, imunossupressão, roupas justas, açúcar, álcool no tratamento, não tratar parceiro na recidiva.", "id": "2-vulvovaginites-vaginose-tr-24"}, {"q": "Como é a clínica da candidíase?", "a": "Prurido que piora com calor, corrimento em leite talhado sem odor, ardor, dispareunia, disúria.", "id": "2-vulvovaginites-vaginose-tr-25"}, {"q": "Achado do KOH 10%?", "a": "Pseudo-hifas.", "id": "2-vulvovaginites-vaginose-tr-26"}, {"q": "Tratamento da não complicada (slide)?", "a": "Fluconazol 150 mg VO dose única ou azólico tópico.", "id": "2-vulvovaginites-vaginose-tr-27"}, {"q": "Definição e conduta na CVVR?", "a": "≥ 4 episódios/ano; cultura, 14 dias de tópico e fluconazol 150 mg semanal por 6 meses.", "id": "2-vulvovaginites-vaginose-tr-28"}, {"q": "Quando tratar o parceiro na candidíase?", "a": "Só com balanite ou dermatite peniana.", "id": "2-vulvovaginites-vaginose-tr-29"}]}, {"t": "h2", "v": "Comparativo final (PARA DECORAR)"}, {"t": "table", "head": ["", "Vaginose", "Candidíase", "Tricomoníase"], "rows": [["Agente", "Polimicrobiano anaeróbio", "<i>Candida</i>", "<i>T. vaginalis</i>"], ["Corrimento", "Fino, branco-acinzentado", "Branco, leite talhado", "Espumoso, amarelo-esverdeado"], ["Odor", "Pescado", "Ausente", "Fétido"], ["Prurido", "Pouco/ausente", "Intenso (piora com calor)", "Frequente"], ["pH", "&gt; 4,5", "Normal", "&gt; 6"], ["Leucócitos", "Ausentes", "Presentes", "Muitos"], ["Microscopia", "Clue cells", "Pseudo-hifas", "Protozoário móvel"], ["Especular", "Sem inflamação", "Vulvovaginite, eritema", "Colo em morango, cervicite"], ["IST? / parceiro?", "Não / não", "Não / só se balanite", "<b>Sim / sim</b>"], ["Tratamento", "Metronidazol ou clindamicina", "Azólico (fluconazol 150 mg)", "Metronidazol"]]}, {"t": "box", "v": "Metronidazol para \"T\" e \"V\" (tricomoníase e vaginose); azólico para \"C\" (candidíase).", "label": "Mnemônico"}, {"t": "q", "v": [{"q": "Corrimento + pH 6,5 + disúria + colo em morango: diagnóstico e conduta?", "a": "Tricomoníase; metronidazol para paciente e parceiro.", "id": "2-vulvovaginites-vaginose-tr-30"}, {"q": "Prurido intenso sem odor + pseudo-hifas: diagnóstico?", "a": "Candidíase.", "id": "2-vulvovaginites-vaginose-tr-31"}, {"q": "Corrimento fino com odor, sem leucócitos, clue cells: diagnóstico?", "a": "Vaginose bacteriana.", "id": "2-vulvovaginites-vaginose-tr-32"}, {"q": "Corrimento com dor pélvica e dor à mobilização do colo: o que afastar?", "a": "DIP (não tratar como vaginite simples).", "id": "2-vulvovaginites-vaginose-tr-33"}]}], "id": "2-vulvovaginites-vaginose-tr"}, {"title": "3. Fisiologia do ciclo menstrual", "sub": "Aula 3 · Prof. Josélio Vitoi Rosa", "blocks": [{"t": "ul", "v": ["Ciclo existe para <b>ovulação</b> e <b>preparo do útero</b>; o útero é <b>passivo</b>.", "Normal: <b>3 a 7 dias, 30 a 80 mL, a cada 24 a 35 dias</b>. Sangue menstrual <b>sem fibrinogênio</b> e fibrinolítico (não coagula).", "A duração do ciclo depende da <b>qualidade e velocidade do desenvolvimento folicular</b>: a <b>fase folicular varia</b>, a <b>lútea é fixa (14 dias)</b>."]}, {"t": "h2", "v": "Terminologia do slide (Aula 3)"}, {"t": "table", "head": ["Termo", "Definição"], "rows": [["Polimenorreia", "Ciclos &lt; 24 dias"], ["Oligomenorreia", "Ciclos &gt; 35 dias"], ["Metrorragia", "Sangramento fora do período menstrual"], ["Hipermenorreia", "Duração do fluxo aumentada"], ["Hipomenorreia", "Duração do fluxo reduzida"], ["Menorragia", "Volume do fluxo aumentado"]]}, {"t": "div", "v": "a Aula 1 e a literatura clássica usam hiper/hipomenorreia para <b>volume</b>; a FIGO hoje fala em \"sangramento uterino anormal\". Leia o enunciado e use a definição da aula cobrada."}, {"t": "q", "v": [{"q": "O que é polimenorreia e oligomenorreia?", "a": "Ciclos &lt; 24 dias e &gt; 35 dias, respectivamente.", "id": "3-fisiologia-do-ciclo-menstr-01"}, {"q": "Na Aula 3, o que é hipermenorreia e o que é menorragia?", "a": "Hipermenorreia = duração aumentada; menorragia = volume aumentado.", "id": "3-fisiologia-do-ciclo-menstr-02"}, {"q": "Por que o sangue menstrual não coagula?", "a": "Não tem fibrinogênio e é fibrinolítico.", "id": "3-fisiologia-do-ciclo-menstr-03"}, {"q": "Qual fase determina a duração do ciclo?", "a": "A folicular (a lútea é fixa em 14 dias).", "id": "3-fisiologia-do-ciclo-menstr-04"}]}, {"t": "h2", "v": "Eixo hipotálamo-hipófise-ovário"}, {"t": "ul", "v": ["<b>GnRH pulsátil</b> (sistema porta) → células gonadotróficas basófilas da <b>adeno-hipófise</b> → FSH e LH pulsáteis.", "<b>Fase folicular: pulsos frequentes, de baixa amplitude.</b> <b>Fase lútea: menos frequentes, de maior amplitude.</b>", "Noradrenalina estimula o GnRH. <cx>[Complemento]</cx> Dopamina inibe prolactina e GnRH; GnRH contínuo dessensibiliza (análogos = \"menopausa química\").", "Feedback: alça ultracurta (GnRH no hipotálamo), curta (hipófise → hipotálamo), longa (esteroides ovarianos).", "<b>Estrogênio baixo/moderado = feedback negativo; alto e sustentado (~200 pg/mL por ~50 h) = feedback positivo</b> → pico de LH."]}, {"t": "h2", "v": "Teoria das duas células, duas gonadotrofinas"}, {"t": "table", "head": ["Célula", "Estímulo", "Produto"], "rows": [["<b>Teca</b>", "<b>LH</b> (AMPc)", "Colesterol → androstenediona e testosterona"], ["<b>Granulosa</b>", "<b>FSH</b> (AMPc)", "<b>Aromatase</b>: androgênio → estrona/estradiol"]]}, {"t": "ul", "v": ["Folículo: primordial → primário → pré-antral (passa a depender do FSH) → antral (cumulus oophorus) → pré-ovulatório (Graaf).", "<b>Microambiente androgênico → atresia.</b> O folículo só ovula se converter o microambiente em estrogênico (aromatase/FSH).", "Recrutamento: ~1000 primordiais na fase lútea tardia; 15 a 30 chegam a pré-antrais; um domina.", "Reserva: <b>~7 milhões às 16–20 semanas</b> de gestação; 1,5 a 2 milhões ao nascer; 300 a 500 mil na puberdade; <b>~400 ovulam</b>. A atresia <b>não para</b> com gravidez nem anovulação."]}, {"t": "q", "v": [{"q": "Explique a teoria das duas células.", "a": "LH na teca produz androgênios; FSH na granulosa ativa a aromatase e converte em estradiol.", "id": "3-fisiologia-do-ciclo-menstr-05"}, {"q": "Como são os pulsos de GnRH na fase folicular e na lútea?", "a": "Folicular: frequentes e de baixa amplitude. Lútea: menos frequentes e de maior amplitude.", "id": "3-fisiologia-do-ciclo-menstr-06"}, {"q": "Qual o gatilho do pico de LH?", "a": "Estradiol alto e sustentado (~200 pg/mL por ~50 h) → feedback positivo.", "id": "3-fisiologia-do-ciclo-menstr-07"}, {"q": "O que acontece com o folículo em microambiente androgênico?", "a": "Atresia.", "id": "3-fisiologia-do-ciclo-menstr-08"}, {"q": "Quando há o número máximo de oócitos e quantos ovulam?", "a": "Às 16–20 semanas de gestação (~7 milhões); ~400 ovulam na vida.", "id": "3-fisiologia-do-ciclo-menstr-09"}, {"q": "A pílula ou a gravidez \"poupam\" folículos?", "a": "Não. A atresia continua.", "id": "3-fisiologia-do-ciclo-menstr-10"}]}, {"t": "h2", "v": "Ovulação e fase lútea"}, {"t": "ul", "v": ["Pico de estrogênio ~3 dias antes da ovulação → <b>pico de LH ~1 dia depois</b>, <b>~36 h antes da ovulação</b>.", "LH: <b>luteiniza a granulosa</b> (progesterona começa ~12 h antes), <b>retoma a meiose até metáfase II</b>, aumenta androgênios tecais (<b>libido</b>).", "Ruptura: progesterona distende a parede; <b>prostaglandinas e histamina</b>; FSH induz enzimas proteolíticas (plasminogênio) e receptores de LH.", "<b>Fase lútea: 14 dias.</b> Progesterona inibe crescimento folicular e faz a <b>transformação secretória</b> do endométrio.", "Sem gravidez: ↓LH → <b>luteólise</b> → ↓E2 e progesterona → <b>FSH volta a subir</b> → novo ciclo.", "Gravidez: <b>hCG mantém o corpo lúteo até ~8 semanas</b>."]}, {"t": "h2", "v": "Padrões hormonais (spoiler de múltipla escolha)"}, {"t": "table", "head": ["FSH / LH", "Estrogênio", "Interpretação", "Compartimento"], "rows": [["<b>Altos</b>", "Baixo", "<b>Hipogonadismo hipergonadotrófico</b>: ovário falhou e perdeu o feedback (IOP, menopausa, Turner, Savage, pós-RT/QT)", "II"], ["<b>Baixos</b>", "Baixo", "<b>Hipogonadismo hipogonadotrófico</b>: falta estímulo central (hipotalâmica funcional, Kallmann, Sheehan, prolactinoma)", "III ou IV"], ["Normais", "Normal", "Eugonadismo (ex.: anovulação/SOP, causas uterinas)", "Vários"]]}, {"t": "p", "v": "<cx>[Complemento]</cx> Padrões que costumam cair em múltipla escolha e não estão no slide: <b>FSH alto com LH normal/baixo</b> = reserva ovariana caindo / transição menopausal inicial (a inibina B cai primeiro e libera seletivamente o FSH); <b>LH/FSH &gt; 2</b> = SOP (pulsos rápidos de GnRH favorecem LH); na pós-menopausa <b>FSH &gt; LH</b>. Regra: pulsos rápidos de GnRH → LH; pulsos lentos → FSH."}, {"t": "q", "v": [{"q": "Quanto tempo antes da ovulação ocorre o pico de LH?", "a": "~36 horas antes.", "id": "3-fisiologia-do-ciclo-menstr-11"}, {"q": "Em que fase da meiose o oócito está na ovulação?", "a": "Metáfase II.", "id": "3-fisiologia-do-ciclo-menstr-12"}, {"q": "Por que a libido aumenta no meio do ciclo?", "a": "O pico de LH aumenta os androgênios tecais.", "id": "3-fisiologia-do-ciclo-menstr-13"}, {"q": "O que mantém o corpo lúteo na gravidez e até quando?", "a": "hCG, até ~8 semanas.", "id": "3-fisiologia-do-ciclo-menstr-14"}, {"q": "Ciclo de 40 dias com fase lútea normal: o que está prolongado?", "a": "A fase folicular (lútea fixa em 14 dias).", "id": "3-fisiologia-do-ciclo-menstr-15"}, {"q": "Em que dia ovula uma mulher com ciclos de 35 dias?", "a": "Por volta do dia 21 (35 − 14).", "id": "3-fisiologia-do-ciclo-menstr-16"}, {"q": "FSH e LH altos com estrogênio baixo: qual compartimento?", "a": "II (ovário) — hipogonadismo hipergonadotrófico.", "id": "3-fisiologia-do-ciclo-menstr-17"}, {"q": "FSH e LH baixos com estrogênio baixo: qual compartimento?", "a": "III ou IV (hipófise ou hipotálamo) — hipogonadotrófico.", "id": "3-fisiologia-do-ciclo-menstr-18"}, {"q": "FSH aumentado com LH normal/baixo sugere o quê? [Complemento]", "a": "Reserva ovariana diminuída / transição menopausal inicial (queda da inibina B).", "id": "3-fisiologia-do-ciclo-menstr-19"}, {"q": "Lesão das células da teca com FSH normal: o que acontece com o estradiol?", "a": "Cai, por falta de substrato androgênico para a aromatase.", "id": "3-fisiologia-do-ciclo-menstr-20"}]}], "id": "3-fisiologia-do-ciclo-menstr"}, {"title": "4. Amenorreias", "sub": "Aula de Amenorreias · Prof. Túlio Gonçalves dos Reis", "blocks": [{"t": "p", "v": "Amenorreia é <b>sinal</b>, não doença: ausência de menstruação na menacme. Para menstruar é preciso eixo íntegro, ovário funcionante, endométrio responsivo e trato pérvio."}, {"t": "table", "head": ["Tipo", "Critério do slide"], "rows": [["<b>Primária</b>", "Até <b>13 anos sem</b> caracteres sexuais secundários, ou até <b>15 anos com</b> caracteres; ou sem menarca ~2 anos após a telarca"], ["<b>Secundária</b>", "<b>3 meses</b> sem menstruar (ciclos regulares) ou <b>6 meses</b> (ciclos irregulares)"], ["<b>Fisiológica</b>", "Gravidez e lactação. <b>Gravidez é a causa mais comum (70%)</b>"]]}, {"t": "div", "v": "o critério pelo tempo após a telarca varia entre fontes (2, 3 ou 5 anos). Na prova, use os critérios de idade (13 sem / 15 com caracteres)."}, {"t": "table", "head": ["Compartimento", "Estrutura", "Exemplos"], "rows": [["I", "Útero e vagina", "Asherman, estenose, MRKH, Morris, hímen imperfurado, septo transverso"], ["II", "Ovário", "IOP, Savage, Turner, menopausa, <b>QT e radioterapia</b>"], ["III", "Hipófise anterior", "Hiperprolactinemia, Sheehan"], ["IV", "SNC / hipotálamo", "Funcional (estresse, exercício, transtorno alimentar), Kallmann"]]}, {"t": "q", "v": [{"q": "Defina amenorreia primária e secundária (slide).", "a": "Primária: 13 anos sem caracteres ou 15 com caracteres. Secundária: 3 meses (regulares) ou 6 meses (irregulares).", "id": "4-amenorreias-01"}, {"q": "Qual a causa mais comum de amenorreia e sua frequência?", "a": "Gravidez, ~70%.", "id": "4-amenorreias-02"}, {"q": "Liste os 4 compartimentos.", "a": "I útero/vagina; II ovário; III hipófise anterior; IV SNC/hipotálamo.", "id": "4-amenorreias-03"}, {"q": "Radioterapia e quimioterapia causam amenorreia em qual compartimento?", "a": "II (ovário).", "id": "4-amenorreias-04"}]}, {"t": "h2", "v": "Mecanismos mais cobrados"}, {"t": "ul", "v": ["<b>Hiperprolactinemia:</b> PRL alta → ↓GnRH → ↓FSH/LH → anovulação → hipoestrogenismo. Clínica: galactorreia, amenorreia (15 a 20%), infertilidade, ↓libido.", "<b>Hipotireoidismo:</b> ↓T4 → ↑TRH e TSH; <cx>[Complemento]</cx> TRH também estimula prolactina.", "<b>SOP/anovulação:</b> estrogênio sem oposição; endométrio responsivo mas sem sangramento de privação espontâneo.", "<b>Sheehan:</b> hemorragia pós-parto → necrose hipofisária → sem gonadotrofinas e <b>sem lactação</b>.", "<b>Asherman:</b> trauma do endométrio basal (curetagem, miomectomia, infecção, tuberculose) → sinéquias."]}, {"t": "h2", "v": "Investigação da amenorreia secundária (roteiro do slide)"}, {"t": "table", "head": ["Passo", "Resultado → interpretação"], "rows": [["1. Anamnese e exame", "—"], ["2. <b>Beta-hCG</b>", "Sempre o primeiro exame"], ["3. <b>TSH e prolactina</b>", "Normais → seguir"], ["4. <b>Teste da progesterona</b>", "<b>Sangrou</b> = endométrio estrogenizado e trato pérvio = <b>anovulação crônica</b> (SOP). Não sangrou → passo 5"], ["5. <b>Estrogênio + progesterona</b> (21 dias)", "<b>Não sangrou</b> = causa <b>estrutural</b> (Asherman) → HSG/histeroscopia. <b>Sangrou</b> = exclui causa anatômica → passo 6"], ["6. <b>FSH</b>", "<b>Alto</b> = compartimento II (IOP, Savage). <b>Baixo</b> = III ou IV → teste do GnRH / RNM"], ["Teste do GnRH", "Gonadotrofinas <b>sobem</b> = hipotálamo; <b>não sobem</b> = hipófise"]]}, {"t": "ul", "v": ["Prolactina: dosar em <b>2 medidas</b>; <b>PRL &gt; 100</b> sugere tumor → RNM de sela. Tratamento: <b>cabergolina ou bromocriptina</b>.", "<b>IOP:</b> falência ovariana <b>antes dos 40 anos</b>, <b>FSH &gt; 25 mUI/mL em 2 ocasiões</b> (alguns usam 40). Causas: <b>irradiação pélvica, quimioterapia</b>, autoimune, tumores. Tratamento: reposição hormonal; reprodução assistida se desejo de gestar.", "Asherman: <b>lise histeroscópica das aderências + DIU</b>."]}, {"t": "q", "v": [{"q": "Qual a sequência de investigação da amenorreia secundária?", "a": "Beta-hCG → TSH e PRL → teste da progesterona → teste E+P → FSH → (teste do GnRH / RNM).", "id": "4-amenorreias-05"}, {"q": "Teste da progesterona positivo significa?", "a": "Endométrio estrogenizado e trato pérvio: anovulação crônica (ex.: SOP).", "id": "4-amenorreias-06"}, {"q": "Teste E+P negativo indica?", "a": "Causa estrutural uterina (ex.: Asherman) → HSG ou histeroscopia.", "id": "4-amenorreias-07"}, {"q": "Teste E+P positivo exclui o quê?", "a": "Causas anatômicas (útero e vagina). Próximo passo: FSH.", "id": "4-amenorreias-08"}, {"q": "FSH alto após E+P positivo indica? E baixo?", "a": "Alto: compartimento II (ovário). Baixo: III ou IV (central).", "id": "4-amenorreias-09"}, {"q": "Como o teste do GnRH diferencia hipotálamo de hipófise?", "a": "Se as gonadotrofinas sobem = hipotálamo; se não sobem = hipófise.", "id": "4-amenorreias-10"}, {"q": "Critérios de IOP do slide?", "a": "&lt; 40 anos com FSH &gt; 25 mUI/mL em duas dosagens.", "id": "4-amenorreias-11"}, {"q": "Prolactina acima de quanto sugere tumor e qual o tratamento?", "a": "&gt; 100; cabergolina ou bromocriptina.", "id": "4-amenorreias-12"}, {"q": "Tratamento do Asherman?", "a": "Lise das aderências por histeroscopia + DIU.", "id": "4-amenorreias-13"}]}, {"t": "h2", "v": "Amenorreia primária"}, {"t": "p", "v": "Roteiro: anamnese e exame → anatomia → cariótipo. <b>Sem caracteres sexuais → cariótipo.</b> <b>Com caracteres → imagem (USG) + cariótipo.</b>"}, {"t": "table", "head": ["", "Turner", "Kallmann", "MRKH", "Morris", "Hímen imperfurado"], "rows": [["Cariótipo", "45,X (60%)", "46,XX", "46,XX", "<b>46,XY</b>", "46,XX"], ["Caracteres", "Ausentes (<b>pubarca normal</b>)", "Infantilismo", "Normais", "Mamas normais, <b>sem pelos</b>", "Normais"], ["Útero", "Presente", "Presente", "<b>Ausente</b>", "<b>Ausente</b>", "Presente"], ["FSH/LH", "<b>Altos</b>", "<b>Baixos</b>", "Normais", "Testosterona alta", "Normais"], ["Pista", "Gônada em fita", "<b>Anosmia</b>", "Anomalia renal", "Hérnia inguinal", "Dor cíclica, hematocolpo"], ["Conduta", "Reposição", "GnRH exógeno", "—", "<b>Gonadectomia + estrogênio</b>", "Cirurgia"]]}, {"t": "div", "v": "o slide chama Morris de \"pseudo-hermafroditismo feminino\"; o correto é <b>masculino</b> (46,XY com fenótipo feminino)."}, {"t": "h2", "v": "Amenorreia e câncer de colo (\"o Túlio falou\")"}, {"t": "p", "v": "A ponte entre os dois temas está no próprio slide: entre as causas de <b>IOP (compartimento II)</b> estão <b>irradiação pélvica e quimioterapia</b>. O tratamento do câncer de colo a partir do IB3 é <b>radioterapia + quimioterapia</b> (ver seção 6). Resultado: amenorreia secundária com <b>FSH &gt; 25 em duas dosagens</b>, estrogênio baixo, teste E+P positivo; tratamento com reposição hormonal."}, {"t": "p", "v": "<cx>[Complemento]</cx> Dois outros mecanismos: a <b>conização/EZT</b> pode causar <b>estenose cervical</b> (compartimento I; o slide lista \"estenose\" entre as causas estruturais), com dor cíclica sem sangramento e teste E+P negativo; e a braquiterapia também pode causar sinéquias. Em jovens, a <b>transposição dos ovários</b> antes da RT preserva a função."}, {"t": "q", "v": [{"q": "Mamas e pelos normais, sem útero, 46,XX: diagnóstico?", "a": "MRKH.", "id": "4-amenorreias-14"}, {"q": "Mamas normais, sem pelos, 46,XY, hérnia inguinal: diagnóstico e conduta?", "a": "Morris (insensibilidade androgênica); gonadectomia + estrogênio.", "id": "4-amenorreias-15"}, {"q": "Amenorreia primária + anosmia: diagnóstico?", "a": "Kallmann.", "id": "4-amenorreias-16"}, {"q": "Por que Turner tem pubarca normal?", "a": "Os androgênios adrenais não dependem do ovário.", "id": "4-amenorreias-17"}, {"q": "Hemorragia no parto e não conseguiu amamentar: diagnóstico?", "a": "Sheehan.", "id": "4-amenorreias-18"}, {"q": "Curetagem prévia + E+P negativo: diagnóstico e exame?", "a": "Asherman; histeroscopia ou HSG.", "id": "4-amenorreias-19"}, {"q": "Corredora, IMC 18, FSH/LH baixos, PRL normal: diagnóstico?", "a": "Amenorreia hipotalâmica funcional.", "id": "4-amenorreias-20"}, {"q": "Mulher de 34 anos tratada com quimiorradiação para câncer de colo evolui com amenorreia: padrão hormonal e compartimento?", "a": "FSH e LH altos, estradiol baixo: insuficiência ovariana (compartimento II), causa citada no slide (irradiação pélvica/QT).", "id": "4-amenorreias-21"}, {"q": "Amenorreia com dor cíclica após conização: mecanismo? [Complemento]", "a": "Estenose cervical com hematometra (compartimento I).", "id": "4-amenorreias-22"}]}], "id": "4-amenorreias"}, {"title": "5. Abdome agudo ginecológico e DIP", "sub": "Aula de Abdome agudo e DIP · Dr. Ricardo Campello", "blocks": [{"t": "h2", "v": "Abdome agudo: classificação por síndrome"}, {"t": "table", "head": ["Síndrome", "Exemplos ginecológicos"], "rows": [["Inflamatória", "DIP aguda"], ["Hemorrágica", "Ectópica rota, rotura de cisto folicular/lúteo, imperfuração himenal, rotura de tumor ovariano (endometrioma)"], ["Vascular", "Torção de anexos (tumores de 5 a 15 cm), torção de mioma subseroso pediculado, necrobiose asséptica de mioma"], ["Perfurativa", "Não ginecológica"]]}, {"t": "ul", "v": ["<b>BHCG sempre</b> na mulher em idade fértil com dor pélvica.", "\"Abdome agudo que se inicia com <b>temperatura &gt; 38 °C raramente é cirúrgico</b>.\" \"A <b>anorexia precede a dor</b> no abdome agudo inflamatório.\"", "Peristaltismo normal <b>não exclui</b> causa cirúrgica. Analgésicos e antibióticos mascaram o quadro.", "Ectópica rota: <b>sinal de Laffont</b> (dor no ombro), <b>grito de Douglas</b>, peso em reto e bexiga, pré-choque → reposição volêmica + cirurgia. Culdocentese não se faz mais."]}, {"t": "h2", "v": "DIP: conceito e agentes"}, {"t": "p", "v": "Infecção <b>ascendente</b>: cervicite → endometrite → salpingite → ooforite/abscesso tubovariano → peritonite pélvica. Principal causa evitável de infertilidade tubária, dor pélvica crônica e ectópica."}, {"t": "ul", "v": ["Agentes: <b><i>N. gonorrhoeae</i> e <i>C. trachomatis</i></b> (principais); <i>M. hominis</i>, <i>Ureaplasma</i>; flora vaginal (enterobactérias, anaeróbios, aeróbios).", "Gonococo pode ser carreado pelo espermatozoide. Início geralmente <b>pós-menstrual</b>, sem atraso menstrual.", "ACO: muco espesso protege, mas aumenta a ectopia (facilita clamídia).", "Epidemiologia: <b>70% das infectadas têm &lt; 25 anos</b>; <b>esterilidade em 12,5 a 25%</b>; <b>dor pélvica crônica/dispareunia em 18%</b>.", "Fatores de risco: múltiplos parceiros, início sexual precoce, <b>DIU</b>, manipulação uterina, <b>DIP prévia</b>, baixo nível socioeconômico, duchas."]}, {"t": "h2", "v": "Clínica e diagnóstico"}, {"t": "ul", "v": ["Dor abdominal aguda (suprapúbica, fossas ilíacas ou difusa); dor intensa súbita → pensar em <b>rotura de abscesso</b>.", "Blumberg positivo; <b>colo doloroso à mobilização</b>, anexos hipersensíveis, massa anexial; <b>fluxo mucopurulento pelo colo</b>; dispareunia recente.", "<b>Febre em apenas 20 a 30%</b> (ausência de febre não exclui).", "Sangramento intermenstrual ou menorragia (endometrite por clamídia).", "Diagnóstico só clínico tem <b>30% de erro</b>. Exames: <b>BHCG</b>, hemograma, VHS, urina; <b>Gram da secreção do colo</b>, cultura para gonococo e clamídia, PCR para clamídia; <b>USG</b> (piossalpinge, abscesso, afastar ectópica); <b>laparoscopia</b> na dúvida.", "30 a 90% das mulheres com obstrução tubária <b>não relatam DIP</b> (DIP silenciosa)."]}, {"t": "h2", "v": "Estadiamento de Monif (spoiler — CAI MUITO)"}, {"t": "table", "head": ["Estádio", "Definição (slide)", "Conduta (slide)"], "rows": [["<b>1</b>", "Endometrite e salpingite <b>sem peritonite</b>", "Antibiótico"], ["<b>2</b>", "Salpingite <b>com peritonite</b>", "Observar 48 h; sem melhora, cirurgia"], ["<b>3</b>", "Salpingite aguda com <b>oclusão tubária</b> ou comprometimento tubovariano; <b>abscesso íntegro</b>", "Observar 48 h; sem melhora, cirurgia"], ["<b>4</b>", "<b>Abscesso tubovariano roto</b>", "<b>Cirurgia imediata</b>"]]}, {"t": "box", "v": "1 = sem peritonite · 2 = com peritonite · 3 = abscesso <b>íntegro</b> · 4 = abscesso <b>roto</b>.", "label": "PARA DECORAR"}, {"t": "p", "v": "<b>Internação (slide):</b> diagnóstico incerto, emergência cirúrgica, suspeita de abscesso pélvico, doença grave, <b>gravidez</b>, <b>adolescência</b>, má adesão, falha do tratamento ambulatorial, impossibilidade de reavaliação. Parceiro: azitromicina 1 g; abstinência."}, {"t": "div", "v": "os esquemas antibióticos do slide (tianfenicol + doxiciclina 10 dias) estão desatualizados; o PCDT atual usa ceftriaxona 500 mg IM + doxiciclina + metronidazol por 14 dias. Como a prova pede só classificação, priorize Monif e critérios."}, {"t": "q", "v": [{"q": "Quais são os agentes principais da DIP?", "a": "<i>Neisseria gonorrhoeae</i> e <i>Chlamydia trachomatis</i>.", "id": "5-abdome-agudo-ginecologico-01"}, {"q": "Descreva a sequência de ascensão da DIP.", "a": "Cervicite → endometrite → salpingite → ooforite/abscesso tubovariano → peritonite pélvica.", "id": "5-abdome-agudo-ginecologico-02"}, {"q": "Qual o momento típico de início da DIP?", "a": "Pós-menstrual, sem atraso menstrual.", "id": "5-abdome-agudo-ginecologico-03"}, {"q": "Em que porcentagem há febre na DIP?", "a": "Apenas 20 a 30%.", "id": "5-abdome-agudo-ginecologico-04"}, {"q": "Qual a taxa de erro do diagnóstico só clínico?", "a": "30%.", "id": "5-abdome-agudo-ginecologico-05"}, {"q": "Defina os 4 estádios de Monif.", "a": "1: endometrite/salpingite sem peritonite. 2: salpingite com peritonite. 3: oclusão tubária/abscesso íntegro. 4: abscesso roto.", "id": "5-abdome-agudo-ginecologico-06"}, {"q": "Monif 3: conduta? Monif 4: conduta?", "a": "3: internar, antibiótico, observar 48 h e operar se não melhorar. 4: cirurgia imediata.", "id": "5-abdome-agudo-ginecologico-07"}, {"q": "Cite 5 indicações de internação na DIP.", "a": "Dúvida diagnóstica, abscesso, gravidez, adolescência, má adesão, falha ambulatorial, doença grave, sem reavaliação.", "id": "5-abdome-agudo-ginecologico-08"}, {"q": "Quais as sequelas da DIP e suas frequências?", "a": "Esterilidade 12,5–25%; dor pélvica crônica/dispareunia 18%; ectópica; hidrossalpinge.", "id": "5-abdome-agudo-ginecologico-09"}, {"q": "\"Febre &gt; 38 °C raramente é cirúrgica\": qual a exceção na DIP?", "a": "Monif 4 (abscesso roto) é cirúrgico imediato.", "id": "5-abdome-agudo-ginecologico-10"}, {"q": "Qual a classificação sindrômica da DIP? E da torção?", "a": "DIP: inflamatória. Torção: vascular.", "id": "5-abdome-agudo-ginecologico-11"}]}], "id": "5-abdome-agudo-ginecologico"}, {"title": "6. Câncer do colo uterino e lesões precursoras", "sub": "Aula de câncer de colo (slide atualizado)", "blocks": [{"t": "h2", "v": "Epidemiologia e HPV"}, {"t": "ul", "v": ["~<b>660 mil casos e 350 mil mortes</b> no mundo (2022); no Brasil ~<b>17 mil casos</b>, ~7% dos cânceres femininos; 4º mais frequente em mulheres no mundo.", "HPV: 80% da população já teve contato; prevalência 54% entre 16 e 25 anos; <b>a maioria regride em até 24 meses</b>. HPV positivo não é câncer: o que importa é a <b>persistência</b>.", "Baixo risco: <b>6 e 11</b> (condilomas). Alto risco: <b>16, 18</b>, 31, 33, 35, 39, 45, 51, 52, 56, 58, 59, 66, 68.", "<b>HPV 16 → carcinoma escamoso; HPV 18 → adenocarcinoma.</b>", "Fatores de risco (slide): HPV, múltiplos parceiros, IST prévia, ACO (ligado ao não uso de preservativo), imunossupressão/HIV, <b>multiparidade</b>, tabagismo, atividade sexual precoce. <b>Menarca precoce NÃO é fator de risco</b> (caiu em prova).", "<cx>[Complemento]</cx> E6 degrada a p53; E7 inativa a pRb → perda do controle do ciclo celular."]}, {"t": "q", "v": [{"q": "Qual o fator principal de progressão do HPV ao câncer?", "a": "Persistência da infecção por HPV oncogênico.", "id": "6-cancer-do-colo-uterino-e-l-01"}, {"q": "Em quanto tempo a maioria das infecções regride?", "a": "Até 24 meses.", "id": "6-cancer-do-colo-uterino-e-l-02"}, {"q": "HPV 6 e 11 causam o quê? E 16 e 18?", "a": "6/11: condilomas (baixo risco). 16/18: alto risco — 16 escamoso, 18 adenocarcinoma.", "id": "6-cancer-do-colo-uterino-e-l-03"}, {"q": "Menarca precoce é fator de risco para câncer de colo?", "a": "Não (pegadinha de prova). Multiparidade é.", "id": "6-cancer-do-colo-uterino-e-l-04"}, {"q": "Qual região do colo concentra as lesões?", "a": "Zona de transformação (junção escamocolunar, metaplasia escamosa).", "id": "6-cancer-do-colo-uterino-e-l-05"}]}, {"t": "h2", "v": "Lesões precursoras"}, {"t": "table", "head": ["Histologia", "Extensão", "Citologia"], "rows": [["NIC I", "Terço inferior", "LSIL"], ["NIC II", "Até 2/3", "HSIL"], ["NIC III", "&gt; 2/3 ou toda a espessura", "HSIL"], ["Carcinoma in situ", "Toda a espessura, sem romper a membrana basal", "—"]]}, {"t": "h2", "v": "Vacina HPV no SUS"}, {"t": "ul", "v": ["<b>9 a 14 anos, meninas e meninos: dose única</b> (NT 41/2024; resgate até 19 anos; inclusão de papilomatose respiratória recorrente).", "Imunossuprimidos 9 a 45 anos: <b>3 doses (0-2-6)</b>.", "Vítimas de violência sexual: <b>9–14 anos 2 doses (0-6)</b>; <b>15–45 anos 3 doses (0-2-6)</b>.", "Tratadas por <b>NIC 2+ ou AIS com EZT/conização</b>: vacinar <b>independente da idade</b>, no ano do procedimento ou até 12 meses depois, 3 doses (0-2-6).", "Quadrivalente: 6, 11, 16, 18. Nonavalente: + 31, 33, 45, 52, 58. <b>Vacina não trata lesão e não substitui o rastreamento.</b>"]}, {"t": "q", "v": [{"q": "Esquema da vacina HPV para 9 a 14 anos no SUS?", "a": "Dose única.", "id": "6-cancer-do-colo-uterino-e-l-06"}, {"q": "Menina de 12 anos vítima de violência sexual: esquema?", "a": "2 doses (0 e 6 meses).", "id": "6-cancer-do-colo-uterino-e-l-07"}, {"q": "Mulher de 29 anos tratada por conização por NIC 3: vacina?", "a": "Sim, independente da idade, 3 doses (0-2-6), até 12 meses após o procedimento.", "id": "6-cancer-do-colo-uterino-e-l-08"}, {"q": "Imunossuprimida de 30 anos: esquema?", "a": "3 doses (0-2-6).", "id": "6-cancer-do-colo-uterino-e-l-09"}]}, {"t": "h2", "v": "Rastreamento"}, {"t": "p", "v": "<b>Citológico tradicional:</b> a partir dos <b>25 anos</b> (vida sexual ativa), 2 anuais e depois a cada <b>3 anos</b>; até os <b>64 anos</b>."}, {"t": "table", "head": ["Citologia", "Conduta (tabela do material)"], "rows": [["ASC-US", "&lt; 25 anos: repetir em 3 anos · 25–29: repetir em 12 meses · ≥ 30: repetir em 6 meses"], ["LSIL", "&lt; 25 anos: repetir em 3 anos · ≥ 25: repetir em 6 meses"], ["ASC-H", "<b>Colposcopia</b> (\"urgente\")"], ["HSIL", "<b>Colposcopia</b> e avaliação para excisão"], ["AGC / AIS", "Colposcopia e investigação glandular (AIS: conização)"]]}, {"t": "p", "v": "<b>Novo rastreamento (slide): DNA-HPV oncogênico, 25 a 64 anos.</b>"}, {"t": "table", "head": ["Resultado do DNA-HPV", "Conduta"], "rows": [["Não detectado", "Repetir em <b>5 anos</b> (HIV/imunossuprimida: <b>3 anos</b>). Negativo a partir dos 60 anos: liberada"], ["<b>HPV 16 ou 18</b>", "<b>Colposcopia direto</b>"], ["Outro oncogênico (não 16/18)", "<b>Citologia reflexa</b> → ASC-US ou pior: colposcopia; normal: repetir DNA-HPV em <b>1 ano</b>"], ["Imunossuprimida com qualquer HPV detectado", "Colposcopia"]]}, {"t": "q", "v": [{"q": "Rastreamento citológico: início, periodicidade e fim?", "a": "25 anos; 2 anuais e depois a cada 3 anos; até 64 anos.", "id": "6-cancer-do-colo-uterino-e-l-10"}, {"q": "ASC-US em mulher de 27 anos? E de 32?", "a": "27: repetir em 12 meses. 32: repetir em 6 meses.", "id": "6-cancer-do-colo-uterino-e-l-11"}, {"q": "LSIL em mulher de 23 anos?", "a": "Repetir citologia em 3 anos.", "id": "6-cancer-do-colo-uterino-e-l-12"}, {"q": "ASC-H e HSIL: conduta?", "a": "Colposcopia.", "id": "6-cancer-do-colo-uterino-e-l-13"}, {"q": "DNA-HPV positivo para HPV 16: conduta?", "a": "Colposcopia direto (sem citologia antes).", "id": "6-cancer-do-colo-uterino-e-l-14"}, {"q": "DNA-HPV positivo para HPV 51 (não 16/18): conduta?", "a": "Citologia reflexa; se ASC-US+ colposcopia, se normal repetir em 1 ano.", "id": "6-cancer-do-colo-uterino-e-l-15"}, {"q": "DNA-HPV negativo: quando repetir na imunocompetente e na HIV?", "a": "5 anos e 3 anos.", "id": "6-cancer-do-colo-uterino-e-l-16"}, {"q": "Mulher de 61 anos com DNA-HPV negativo?", "a": "Liberada do rastreamento (o próximo ultrapassaria 64 anos).", "id": "6-cancer-do-colo-uterino-e-l-17"}]}, {"t": "h2", "v": "Colposcopia, biópsia e clínica"}, {"t": "ul", "v": ["Ácido acético 5%: áreas <b>acetobrancas</b>; achados: <b>pontilhado, mosaico, vasos atípicos</b>.", "<b>Lugol (Schiller):</b> epitélio com glicogênio cora; área <b>iodo-negativa</b> = suspeita (também metaplasia imatura, inflamação, atrofia). <b>Schiller não confirma câncer: biópsia confirma.</b>", "Lesão macroscópica (vegetante, friável) no colo → <b>coletar CP e biopsiar</b>.", "Conização: diagnóstica e terapêutica (CAF/bisturi frio); risco de insuficiência cervical e parto prematuro.", "Clínica: inicial pode ser assintomático; <b>sangramento pós-coital (sinusiorragia)</b>, intermenstrual, corrimento. Avançado: corrimento em \"água de carne\", dor pélvica, edema de MMII, hidronefrose, insuficiência renal.", "Histologia: <b>escamoso ~80% (HPV 16)</b>; <b>adenocarcinoma ~15% (HPV 18)</b>; raros: adenoescamoso, neuroendócrino, pequenas células."]}, {"t": "h2", "v": "Estadiamento FIGO 2018 (CAI MUITO)"}, {"t": "table", "head": ["Estádio", "Definição"], "rows": [["IA1 / IA2", "Microscópico: invasão ≤ 3 mm / &gt; 3 e &lt; 5 mm"], ["IB1 / IB2 / IB3", "Restrito ao colo, invasão &gt; 5 mm: ≤ 2 cm / &gt; 2 a 4 cm / &gt; 4 cm"], ["IIA1 / IIA2", "2/3 superiores da vagina, sem paramétrio: ≤ 4 cm / &gt; 4 cm"], ["<b>IIB</b>", "<b>Paramétrio</b>, sem parede pélvica"], ["IIIA", "Terço inferior da vagina"], ["<b>IIIB</b>", "<b>Parede pélvica, hidronefrose ou rim não funcionante</b>"], ["IIIC1 / IIIC2", "Linfonodos <b>pélvicos</b> / <b>para-aórticos</b>"], ["IVA / IVB", "Bexiga ou reto / <b>metástase à distância</b>"]]}, {"t": "h2", "v": "Tratamento (slide)"}, {"t": "ul", "v": ["NIC I/LSIL: observação em casos selecionados. <b>NIC II/III (HSIL): EZT/conização</b> (ablação em casos apropriados). AIS: conização.", "IA1 sem desejo reprodutivo: <b>histerectomia total</b> (+ salpingo-ooforectomia). Com desejo: conização (IA1) ou <b>traquelectomia radical</b> (IA1, IA2, IB1).", "<b>Cirúrgico até IB2</b> (histerectomia radical + avaliação linfonodal).", "<b>A partir de IB3 (e IIA, IIB, III, IVA): radioterapia + quimioterapia</b> (RT externa + braquiterapia + platina).", "IVB: quimioterapia paliativa, RT paliativa, imunoterapia em casos específicos, cuidados paliativos."]}, {"t": "box", "v": "IIB = paramétrio · IIIB = parede/hidronefrose · IIIC1 = pélvico · IIIC2 = para-aórtico · IVB = distante · cirurgia até IB2 · RT+QT a partir de IB3.", "label": "PARA DECORAR"}, {"t": "q", "v": [{"q": "Qual o tipo histológico mais comum e qual HPV se associa a ele? E o adenocarcinoma?", "a": "Escamoso (~80%), HPV 16. Adenocarcinoma (~15%), HPV 18.", "id": "6-cancer-do-colo-uterino-e-l-18"}, {"q": "Qual o sintoma clássico do câncer de colo?", "a": "Sangramento pós-coital (sinusiorragia).", "id": "6-cancer-do-colo-uterino-e-l-19"}, {"q": "Teste de Schiller iodo-negativo confirma câncer?", "a": "Não; a biópsia confirma.", "id": "6-cancer-do-colo-uterino-e-l-20"}, {"q": "Lesão vegetante e friável no colo: conduta?", "a": "Coletar o CP e biopsiar a lesão.", "id": "6-cancer-do-colo-uterino-e-l-21"}, {"q": "Invasão de 8 mm, tumor de 3 cm restrito ao colo: estádio?", "a": "IB2.", "id": "6-cancer-do-colo-uterino-e-l-22"}, {"q": "Paramétrio acometido: estádio?", "a": "IIB.", "id": "6-cancer-do-colo-uterino-e-l-23"}, {"q": "Hidronefrose por invasão da parede pélvica: estádio?", "a": "IIIB.", "id": "6-cancer-do-colo-uterino-e-l-24"}, {"q": "Linfonodo para-aórtico: estádio? Metástase pulmonar?", "a": "IIIC2; IVB.", "id": "6-cancer-do-colo-uterino-e-l-25"}, {"q": "Até qual estádio o tratamento é cirúrgico? A partir de qual é RT+QT?", "a": "Cirúrgico até IB2; RT+QT a partir de IB3.", "id": "6-cancer-do-colo-uterino-e-l-26"}, {"q": "Mulher de 33 anos com câncer inicial que quer engravidar: opção?", "a": "Conização (IA1) ou traquelectomia radical (IA1–IB1).", "id": "6-cancer-do-colo-uterino-e-l-27"}, {"q": "Mulher de 48 anos, prole completa, IA1: tratamento?", "a": "Histerectomia total.", "id": "6-cancer-do-colo-uterino-e-l-28"}]}], "id": "6-cancer-do-colo-uterino-e-l"}, {"title": "7. Neoplasias do corpo uterino: mioma, pólipo, adenomiose e endométrio", "sub": "Aula · Prof. Didier Castellano", "blocks": [{"t": "h2", "v": "Leiomioma"}, {"t": "ul", "v": ["Neoplasia benigna de <b>músculo liso e tecido fibroso</b>; neoplasia mais comum do miométrio, do útero e da mulher.", "<b>20 a 30%</b> das mulheres; <b>40 a 50% acima de 40 anos</b>; <b>múltiplos em ~84%</b>; maioria assintomática (conduta expectante). <cx>[Complemento]</cx> 4–5× mais em negras (Aula 1).", "Etiopatogenia: <b>predisposição genética + receptores de estrogênio e progesterona aumentados</b> → cresce no menacme e na gravidez, <b>regride na menopausa</b>. <b>Crescer na pós-menopausa = suspeitar de malignidade.</b>", "Tamanho (slide): pequeno (na pelve), médio (até o ponto médio umbílico-púbico), grande (ultrapassa).", "Localização: <b>submucoso</b> (sangra muito, infertilidade, pode ser \"parido\"), intramural, <b>subseroso</b> (cresce sem sintoma, depois comprime; pode ser pediculado), cervical, intraligamentar."]}, {"t": "table", "head": ["Degeneração", "Contexto"], "rows": [["<b>Hialina</b>", "<b>A mais comum</b>"], ["<b>Vermelha (carnosa)</b>", "<b>Gravidez e puerpério</b> (necrose hemorrágica, dor aguda)"], ["Cística", "Necrose central por crescimento rápido"], ["Mucoide", "Miomas grandes"], ["Gordurosa", "Menopausa"], ["Calcificação", "Após necrose"], ["Sarcomatosa", "Muito rara (0,07 a 0,5%)"]]}, {"t": "q", "v": [{"q": "Qual a frequência do mioma e com que frequência é múltiplo?", "a": "20–30% das mulheres (40–50% após 40 anos); múltiplo em ~84%.", "id": "7-neoplasias-do-corpo-uterin-01"}, {"q": "Por que o mioma regride na menopausa?", "a": "É hormônio-dependente (receptores de estrogênio e progesterona).", "id": "7-neoplasias-do-corpo-uterin-02"}, {"q": "Mioma que cresce na pós-menopausa sugere o quê?", "a": "Malignidade (sarcoma) — indicação de tratamento invasivo.", "id": "7-neoplasias-do-corpo-uterin-03"}, {"q": "Qual a degeneração mais comum? E a típica da gravidez?", "a": "Hialina; vermelha (carnosa).", "id": "7-neoplasias-do-corpo-uterin-04"}, {"q": "Qual a frequência da degeneração sarcomatosa?", "a": "0,07 a 0,5%.", "id": "7-neoplasias-do-corpo-uterin-05"}]}, {"t": "h2", "v": "Clínica e diagnóstico"}, {"t": "p", "v": "Depende de <b>número, tamanho, localização, degeneração, pedículo e compressão</b>: maioria assintomática; <b>SUA</b> (submucoso), dor pélvica/lombar, polaciúria e urgência (anteriores), constipação (posteriores), aumento abdominal, <b>abdome agudo</b> (torção/degeneração), <b>infertilidade</b> (submucoso), anemia, uretero-hidronefrose."}, {"t": "ul", "v": ["<b>USG: método de escolha</b> (número, tamanho, localização, cavidade, degenerações).", "<b>Histeroscopia</b>: esclarece SUA, confirma submucoso/pólipo e permite ressecção.", "RNM: não é rotina; úteros volumosos, diferencial de massa sólida, planejamento cirúrgico.", "<b>Síndrome de Meigs</b>: tumor benigno do ovário + <b>ascite + derrame pleural</b>. <cx>[Complemento]</cx> O tumor clássico é o <b>fibroma ovariano</b> (o slide diz \"mioma ovariano\")."]}, {"t": "h2", "v": "Tratamento"}, {"t": "table", "head": ["Opção", "Indicação / detalhe do slide"], "rows": [["<b>Expectante</b>", "Jovem com mioma pequeno assintomático; peri/pós-menopausa assintomática; mioma estável ou regredindo"], ["<b>Medicamentoso</b> (paliativo)", "AINH, ácido mefenâmico, ácido tranexâmico, DIU-LNG 20 µg/dia, <b>análogo de GnRH</b> (menopausa química, <b>máximo 6 meses</b> por osteoporose; reduz tumor e vascularização antes da cirurgia)"], ["Indicações invasivas", "SUA refratário, anemia, suspeita de malignidade, <b>crescimento pós-menopausa</b>, dor/compressão, infertilidade"], ["<b>Miomectomia histeroscópica</b>", "Submucoso; alta &lt; 24 h; recorrência ~30%"], ["Miomectomia laparoscópica", "Subserosos/intramurais <b>&lt; 5 cm, até 5 miomas</b>"], ["Miomectomia laparotômica", "Casos maiores ou complexos"], ["<b>Histerectomia</b>", "Definitiva; por vídeo se útero até ~250 cm³, acima disso laparotomia"], ["<b>Embolização</b>", "Muito sintomática que <b>não quer retirar o útero</b>; risco de isquemia ovariana e <b>menopausa precoce</b>"]]}, {"t": "box", "v": "quer fertilidade → miomectomia · prole completa e sintomática → histerectomia · preservar útero sem gestar → embolização.", "label": "Regra prática"}, {"t": "h2", "v": "Pólipo, adenomiose e câncer de endométrio (resumo)"}, {"t": "ul", "v": ["<b>Pólipo endometrial:</b> sangramento; exérese por <b>vídeo-histeroscopia</b>. <b>Endocervical:</b> exérese ambulatorial.", "<b>Adenomiose</b> (endométrio no miométrio): tríade <b>SUA + dismenorreia grave e progressiva + útero aumentado</b> (difuso, globoso); tratamento clínico (progestagênio, danazol, GnRH, Mirena) ou <b>histerectomia</b>.", "<b>Câncer de endométrio:</b> 75–80% na peri/pós-menopausa (média 61 anos); <b>sangramento em ~90%</b>; lógica do <b>estrogênio sem oposição</b> (obesidade, SOP, nuliparidade, tamoxifeno, estrogênio isolado). ACO e tabagismo têm RR &lt; 1. Adenocarcinoma endometrioide 80%. Melhor exame: <b>vídeo-histeroscopia com biópsia</b>. Estadiamento cirúrgico (HTA + SOB)."]}, {"t": "q", "v": [{"q": "Qual o método de escolha para diagnosticar mioma?", "a": "Ultrassonografia.", "id": "7-neoplasias-do-corpo-uterin-06"}, {"q": "Qual mioma causa mais sangramento e infertilidade?", "a": "Submucoso.", "id": "7-neoplasias-do-corpo-uterin-07"}, {"q": "O que é a síndrome de Meigs?", "a": "Tumor benigno de ovário (fibroma) com ascite e derrame pleural.", "id": "7-neoplasias-do-corpo-uterin-08"}, {"q": "Por quanto tempo pode-se usar análogo de GnRH e por quê?", "a": "No máximo 6 meses, pelo risco de osteoporose (menopausa química).", "id": "7-neoplasias-do-corpo-uterin-09"}, {"q": "Cite as indicações de tratamento invasivo do mioma.", "a": "SUA refratário, anemia, suspeita de malignidade, crescimento pós-menopausa, dor/compressão, infertilidade.", "id": "7-neoplasias-do-corpo-uterin-10"}, {"q": "Mioma submucoso com desejo de gestar: conduta?", "a": "Miomectomia histeroscópica.", "id": "7-neoplasias-do-corpo-uterin-11"}, {"q": "Limite da miomectomia laparoscópica no slide?", "a": "Miomas &lt; 5 cm, até 5 miomas.", "id": "7-neoplasias-do-corpo-uterin-12"}, {"q": "Qual o risco da embolização?", "a": "Isquemia ovariana com menopausa precoce.", "id": "7-neoplasias-do-corpo-uterin-13"}, {"q": "Gestante com dor aguda sobre mioma conhecido: hipótese?", "a": "Degeneração vermelha.", "id": "7-neoplasias-do-corpo-uterin-14"}, {"q": "Tríade da adenomiose?", "a": "SUA, dismenorreia progressiva e útero aumentado.", "id": "7-neoplasias-do-corpo-uterin-15"}, {"q": "Mecanismo comum dos fatores de risco do câncer de endométrio?", "a": "Estrogênio sem oposição de progesterona.", "id": "7-neoplasias-do-corpo-uterin-16"}]}], "id": "7-neoplasias-do-corpo-uterin"}, {"title": "8. Mastologia", "sub": "Aula de Mastologia (11/09/2025) — slide curto, várias partes são [Complemento]", "blocks": [{"t": "h2", "v": "Queixas e risco"}, {"t": "ul", "v": ["<b>Mastalgia cíclica</b>: alterações hormonais do ciclo; pode associar-se a trauma. Para mastalgia <b>intensa</b>, a aula cita <b>tamoxifeno</b> (antiestrogênico).", "<b>Nuliparidade é fator de risco</b>: a mama só amadurece após a <b>primeira gestação a termo</b>; células ductais maduras resistem melhor a mecanismos epigenéticos.", "Após 50 anos a mama é <b>liposubstituída</b>: nódulo aparece mais branco → favorece a <b>mamografia</b>."]}, {"t": "div", "v": "tamoxifeno para mastalgia é off-label e reservado a casos refratários; antes vêm medidas conservadoras. Na prova, \"mastalgia intensa\" → tamoxifeno (slide)."}, {"t": "p", "v": "<cx>[Complemento]</cx> Rastreio: MS/INCA mamografia bienal 50–69 anos; SBM/CBR/FEBRASGO anual a partir dos 40."}, {"t": "h2", "v": "Descarga papilar"}, {"t": "ul", "v": ["<b>Descarga papilar, por si só, não é patologia mamária.</b> Não encaminhar de imediato.", "Passos: <b>dosar prolactina e TSH</b> → <b>pesquisar medicamentos</b> (não precisa suspender; explicar) → <b>mamografia só se &gt; 50 anos e nunca fez</b>. Não se pede mamografia por descarga ceroláctea.", "<b>Sanguinolenta unilateral → papiloma intraductal</b> (benigno), mas <b>encaminhar ao mastologista para biópsia</b> (pode pedir MMG ou USG)."]}, {"t": "q", "v": [{"q": "Por que a nuliparidade aumenta o risco de câncer de mama (aula)?", "a": "A mama só amadurece após a primeira gestação a termo; células ductais imaturas são menos resistentes.", "id": "8-mastologia-01"}, {"q": "Tratamento da mastalgia intensa segundo a aula?", "a": "Tamoxifeno.", "id": "8-mastologia-02"}, {"q": "Descarga láctea bilateral em uso de antipsicótico: conduta?", "a": "Dosar prolactina e TSH, pesquisar medicamentos (sem suspender automaticamente).", "id": "8-mastologia-03"}, {"q": "Quando pedir mamografia na descarga ceroláctea?", "a": "Só se &gt; 50 anos e nunca fez.", "id": "8-mastologia-04"}, {"q": "Descarga sanguinolenta unilateral: causa provável e conduta?", "a": "Papiloma intraductal; encaminhar ao mastologista para biópsia.", "id": "8-mastologia-05"}]}, {"t": "h2", "v": "Mastites"}, {"t": "table", "head": ["", "Puerperal", "Não puerperal"], "rows": [["Contexto", "Lactação; abaulamento, dor, febre", "<b>Diabético</b> (tratar abscesso + controlar DM); <b>tabagista</b> (seios lactíferos: subareolar recidivante)"], ["Conduta", "<b>Compressa fria + esvaziar a mama</b> (bebê mama)", "<b>Cefalexina, amoxicilina ou clindamicina</b> + analgésico + controle da temperatura + <b>drenagem do abscesso</b>"], ["Amamentação", "<b>Não suspender</b>", "—"], ["Detalhe", "<cx>[Complemento]</cx> <i>S. aureus</i>; abscesso → ATB e drenagem", "<b>Compressa quente não resolve</b>; recidiva no tabagista → amputação de papila"]]}, {"t": "h2", "v": "Paget, mama acessória, BI-RADS 3 e biópsias"}, {"t": "ul", "v": ["<b>Doença de Paget:</b> <b>prurido mamilar unilateral</b>, ~<b>50 anos</b> → <b>corticoide tópico 30 dias</b> → sem melhora, <b>biópsia</b>. Material: Paget = carcinoma in situ.", "<b>Mama acessória axilar:</b> surge após a adolescência ou na gravidez; incompleta ou completa (sai leite).", "<b>Retração de pele fala a favor de malignidade.</b>", "<b>BI-RADS 3:</b> nódulo de <b>margens circunscritas e eixo paralelo à pele</b> → <b>controle semestral</b>. <cx>[Complemento]</cx> Risco &lt; 2%; BI-RADS 4 e 5 → biópsia.", "<b>PAAF</b> = células soltas (se não sai nada, o nódulo é mais <b>sólido</b>); <b>core biopsy</b> = fragmento tecidual; <b>mamotomia</b> = tecido, retira <b>microcalcificações suspeitas</b>."]}, {"t": "div", "v": "Paget do mamilo se associa, na maioria, a carcinoma ductal subjacente (in situ ou invasivo). Na prova, use \"carcinoma in situ\" (material) e lembre: lesão persistente → biópsia."}, {"t": "h2", "v": "Câncer de mama e prótese"}, {"t": "ul", "v": ["Principais: <b>carcinomas ductais</b>. Estadiamento <b>TNM</b>. Metástases: <b>osso, fígado, pulmão, cérebro</b>.", "<b>Tamoxifeno diminui recidiva</b> (<cx>[Complemento]</cx> receptor hormonal positivo; agonista no endométrio).", "<b>Carcinoma inflamatório:</b> lembrar sempre e <b>encaminhar rapidamente</b> (<cx>[Complemento]</cx> eritema, edema, casca de laranja, sem melhora com antibiótico).", "Subtipos: <b>luminal A, luminal B, HER2, triplo negativo</b> — cada um com tratamento específico (<cx>[Complemento]</cx> hormonioterapia; anti-HER2/trastuzumabe; triplo negativo só QT, pior prognóstico).", "<b>Prótese não muda o rastreio.</b> Suspeita de prótese rota → <b>RNM sem contraste</b>. <b>Linfoma anaplásico de grandes células</b> associado ao silicone (seroma)."]}, {"t": "q", "v": [{"q": "Puérpera com febre, dor e abaulamento mamário: conduta?", "a": "Compressa fria e esvaziamento da mama; manter a amamentação.", "id": "8-mastologia-06"}, {"q": "Diabética com abscesso mamário: conduta?", "a": "Antibiótico (cefalexina/amoxicilina/clindamicina), drenagem do abscesso e controle do diabetes.", "id": "8-mastologia-07"}, {"q": "Mastite do tabagista: onde ocorre e o que pode exigir?", "a": "Seios lactíferos (subareolar recidivante); pode exigir amputação de papila.", "id": "8-mastologia-08"}, {"q": "Compressa quente trata abscesso mamário?", "a": "Não; é preciso drenar.", "id": "8-mastologia-09"}, {"q": "Prurido mamilar unilateral aos 50 anos: conduta?", "a": "Corticoide tópico 30 dias; sem melhora, biópsia (Paget).", "id": "8-mastologia-10"}, {"q": "BI-RADS 3: características e conduta (slide)?", "a": "Margens circunscritas, eixo paralelo à pele; controle semestral.", "id": "8-mastologia-11"}, {"q": "Diferencie PAAF, core e mamotomia.", "a": "PAAF: células soltas. Core: fragmento tecidual. Mamotomia: tecido e microcalcificações.", "id": "8-mastologia-12"}, {"q": "PAAF que não aspira nada sugere?", "a": "Nódulo sólido.", "id": "8-mastologia-13"}, {"q": "Sítios de metástase do câncer de mama?", "a": "Osso, fígado, pulmão e cérebro.", "id": "8-mastologia-14"}, {"q": "Cite os 4 subtipos moleculares.", "a": "Luminal A, luminal B, HER2 e triplo negativo.", "id": "8-mastologia-15"}, {"q": "Suspeita de prótese rota: exame? E seroma tardio?", "a": "RNM sem contraste; linfoma anaplásico de grandes células.", "id": "8-mastologia-16"}]}], "id": "8-mastologia"}, {"title": "Revisão final misturada", "sub": "Agora tudo já foi lido — perguntas cruzando os temas", "blocks": [{"t": "q", "v": [{"q": "Gestante com corrimento fino, odor de peixe e clue cells: tratamento do slide?", "a": "Metronidazol 250 mg VO 8/8 h por 7 dias.", "id": "revisao-final-misturada-01"}, {"q": "Corrimento espumoso + colo em morango: quem tratar?", "a": "Paciente e parceiro (metronidazol).", "id": "revisao-final-misturada-02"}, {"q": "5 episódios de candidíase em 1 ano: conduta?", "a": "Cultura, tópico 14 dias e fluconazol 150 mg semanal por 6 meses.", "id": "revisao-final-misturada-03"}, {"q": "Abscesso tubovariano íntegro: Monif e conduta?", "a": "Monif 3; internar, observar 48 h, cirurgia se não melhorar.", "id": "revisao-final-misturada-04"}, {"q": "DNA-HPV positivo para HPV 18: conduta?", "a": "Colposcopia.", "id": "revisao-final-misturada-05"}, {"q": "Tumor de colo de 5 cm restrito ao colo: estádio e tratamento?", "a": "IB3; radioterapia + quimioterapia.", "id": "revisao-final-misturada-06"}, {"q": "Tratada por quimiorradiação de colo, amenorreia: FSH esperado?", "a": "Alto (&gt; 25 em duas dosagens) — insuficiência ovariana, compartimento II.", "id": "revisao-final-misturada-07"}, {"q": "Teste da progesterona positivo: diagnóstico?", "a": "Anovulação crônica (ex.: SOP).", "id": "revisao-final-misturada-08"}, {"q": "FSH e LH baixos, estradiol baixo, PRL normal: compartimento?", "a": "III ou IV (central).", "id": "revisao-final-misturada-09"}, {"q": "Pico de LH em relação à ovulação?", "a": "~36 h antes.", "id": "revisao-final-misturada-10"}, {"q": "Mioma com crescimento após a menopausa: o que fazer?", "a": "Tratamento invasivo — suspeita de malignidade.", "id": "revisao-final-misturada-11"}, {"q": "Degeneração mais comum do mioma?", "a": "Hialina.", "id": "revisao-final-misturada-12"}, {"q": "Descarga sanguinolenta unilateral: conduta?", "a": "Encaminhar ao mastologista para biópsia (papiloma provável).", "id": "revisao-final-misturada-13"}, {"q": "BI-RADS 3: conduta?", "a": "Controle semestral.", "id": "revisao-final-misturada-14"}, {"q": "Mastite puerperal: suspender amamentação?", "a": "Não.", "id": "revisao-final-misturada-15"}, {"q": "Fator que NÃO é de risco para câncer de colo: multiparidade ou menarca precoce?", "a": "Menarca precoce (multiparidade é fator de risco).", "id": "revisao-final-misturada-16"}]}, {"t": "h2", "v": "O que você precisa conseguir escrever na discursiva"}, {"t": "ul", "v": ["<b>Vulvovaginites:</b> agente, corrimento, odor, prurido, pH, microscopia, especular, tratamento e parceiro — use a tabela da seção 2.", "<b>DIP:</b> conceito ascendente, agentes (gonococo e clamídia), clínica, exames e <b>Monif 1–4</b> com conduta.", "<b>Mama:</b> descarga (endócrina × sanguinolenta), mastites (puerperal × não puerperal), Paget, BI-RADS 3, biópsias, subtipos, prótese.", "<b>Colo:</b> HPV 16/18, rastreio citológico e DNA-HPV, vacina, FIGO 2018, cirurgia até IB2 e RT+QT a partir de IB3.", "<b>Mioma:</b> epidemiologia, hormônio-dependência, localização × sintoma, degenerações, USG, tratamento escalonado.", "<b>Ciclo:</b> eixo, duas células, feedback, pico de LH ~36 h antes, fase lútea fixa, padrões hiper/hipogonadotróficos.", "<b>Amenorreia + colo:</b> roteiro BHCG → TSH/PRL → progesterona → E+P → FSH; RT/QT → IOP (FSH alto); conização → estenose (compartimento I)."]}], "id": "revisao-final-misturada"}], "cards": [{"id": "1-anamnese-01", "topic": "1-anamnese", "q": "Quais são os parâmetros do ciclo menstrual normal no slide?", "a": "Intervalo de 24 a 35 dias, fluxo de 3 a 7 dias, volume de 30 a 80 mL."}, {"id": "1-anamnese-02", "topic": "1-anamnese", "q": "Qual o primeiro exame diante de sangramento na pós-menopausa?", "a": "USG transvaginal (avaliar o endométrio); depois histeroscopia com biópsia se indicado."}, {"id": "1-anamnese-03", "topic": "1-anamnese", "q": "Qual medicamento obriga a investigar sangramento como possível doença endometrial?", "a": "Tamoxifeno."}, {"id": "1-anamnese-04", "topic": "1-anamnese", "q": "Qual exame é obrigatório em toda dor pélvica na idade reprodutiva?", "a": "Beta-hCG."}, {"id": "2-vulvovaginites-vaginose-tr-01", "topic": "2-vulvovaginites-vaginose-tr", "q": "Qual o pH vaginal normal na menacme e na pós-menopausa (slide)?", "a": "Menacme: 3,5 a 4,5. Pré-púbere e pós-menopausa: 5 a 7."}, {"id": "2-vulvovaginites-vaginose-tr-02", "topic": "2-vulvovaginites-vaginose-tr", "q": "Cite 4 fatores que alcalinizam o pH vaginal.", "a": "Sêmen, sangue menstrual, muco cervical, duchas/antibióticos, IST, gravidez/menopausa."}, {"id": "2-vulvovaginites-vaginose-tr-03", "topic": "2-vulvovaginites-vaginose-tr", "q": "PEGADINHA: pós-menopausa assintomática com pH 6 tem vaginose?", "a": "Não. pH 5 a 7 é normal nessa fase; pH isolado não fecha VB."}, {"id": "2-vulvovaginites-vaginose-tr-04", "topic": "2-vulvovaginites-vaginose-tr", "q": "Qual a causa mais comum de corrimento e qual a frequência?", "a": "Vaginose bacteriana: 40 a 50% dos corrimentos."}, {"id": "2-vulvovaginites-vaginose-tr-05", "topic": "2-vulvovaginites-vaginose-tr", "q": "A VB é mais comum em qual grupo?", "a": "Mulheres negras (3×)."}, {"id": "2-vulvovaginites-vaginose-tr-06", "topic": "2-vulvovaginites-vaginose-tr", "q": "Por que se chama vaginose e não vaginite?", "a": "Não há inflamação nem leucócitos; é disbiose."}, {"id": "2-vulvovaginites-vaginose-tr-07", "topic": "2-vulvovaginites-vaginose-tr", "q": "Explique o odor de peixe e por que piora após o coito.", "a": "Anaeróbios produzem aminas que volatilizam em pH alto; o sêmen é alcalino."}, {"id": "2-vulvovaginites-vaginose-tr-08", "topic": "2-vulvovaginites-vaginose-tr", "q": "Cite os 4 elementos diagnósticos do slide.", "a": "Clínica, pH &gt; 4,5, teste das aminas positivo (KOH 10%), clue cells ≥ 20%."}, {"id": "2-vulvovaginites-vaginose-tr-09", "topic": "2-vulvovaginites-vaginose-tr", "q": "Fatores de risco e de proteção da VB?", "a": "Risco: múltiplos parceiros e ducha. Proteção: preservativo e ACO combinado."}, {"id": "2-vulvovaginites-vaginose-tr-10", "topic": "2-vulvovaginites-vaginose-tr", "q": "Tratamento da VB na não gestante?", "a": "Metronidazol 500 mg VO 12/12 h por 7 dias (ou gel 0,75% 5 noites, ou clindamicina creme 7 noites)."}, {"id": "2-vulvovaginites-vaginose-tr-11", "topic": "2-vulvovaginites-vaginose-tr", "q": "Tratamento da VB na gestante segundo o slide?", "a": "Metronidazol 250 mg VO 8/8 h por 7 dias (ou clindamicina 300 mg 12/12 h 7 dias)."}, {"id": "2-vulvovaginites-vaginose-tr-12", "topic": "2-vulvovaginites-vaginose-tr", "q": "Complicações da VB na gestação?", "a": "Rotura prematura de membranas (~7,3×), parto prematuro, endometrite pós-cesárea."}, {"id": "2-vulvovaginites-vaginose-tr-13", "topic": "2-vulvovaginites-vaginose-tr", "q": "Trata o parceiro na VB?", "a": "Não, de rotina."}, {"id": "2-vulvovaginites-vaginose-tr-14", "topic": "2-vulvovaginites-vaginose-tr", "q": "Qual o agente da tricomoníase e como se transmite?", "a": "<i>Trichomonas vaginalis</i>, protozoário flagelado; transmissão exclusivamente sexual."}, {"id": "2-vulvovaginites-vaginose-tr-15", "topic": "2-vulvovaginites-vaginose-tr", "q": "Qual pH o tricomonas prefere / qual o pH do slide para o diagnóstico?", "a": "Acima de 6."}, {"id": "2-vulvovaginites-vaginose-tr-16", "topic": "2-vulvovaginites-vaginose-tr", "q": "Descreva o corrimento e o sinal clássico ao especular.", "a": "Espumoso, amarelo-esverdeado, fétido; colo em morango (colpite focal/difusa)."}, {"id": "2-vulvovaginites-vaginose-tr-17", "topic": "2-vulvovaginites-vaginose-tr", "q": "Com qual IST a tricomoníase se associa?", "a": "Gonorreia."}, {"id": "2-vulvovaginites-vaginose-tr-18", "topic": "2-vulvovaginites-vaginose-tr", "q": "Como se confirma no consultório?", "a": "Exame a fresco mostrando protozoário móvel (com muitos leucócitos)."}, {"id": "2-vulvovaginites-vaginose-tr-19", "topic": "2-vulvovaginites-vaginose-tr", "q": "Esquema do slide para homem e para mulher?", "a": "Homem: metronidazol 2 g dose única. Mulher: 500 mg 12/12 h por 7 dias."}, {"id": "2-vulvovaginites-vaginose-tr-20", "topic": "2-vulvovaginites-vaginose-tr", "q": "Trata o parceiro? E o gel?", "a": "Sim, sempre. O gel de metronidazol só alivia sintomas."}, {"id": "2-vulvovaginites-vaginose-tr-21", "topic": "2-vulvovaginites-vaginose-tr", "q": "Quando tratar a gestante, segundo o slide?", "a": "A partir do terceiro mês."}, {"id": "2-vulvovaginites-vaginose-tr-22", "topic": "2-vulvovaginites-vaginose-tr", "q": "Por que achar Candida no exame não significa doença?", "a": "Ela é comensal em 20 a 50% das mulheres saudáveis."}, {"id": "2-vulvovaginites-vaginose-tr-23", "topic": "2-vulvovaginites-vaginose-tr", "q": "Qual forma da Candida coloniza e qual causa infecção?", "a": "Levedura coloniza; pseudo-hifa é a forma invasiva."}, {"id": "2-vulvovaginites-vaginose-tr-24", "topic": "2-vulvovaginites-vaginose-tr", "q": "Cite 5 condições que perpetuam a candidíase.", "a": "Antibiótico, DM, gravidez, ACO, imunossupressão, roupas justas, açúcar, álcool no tratamento, não tratar parceiro na recidiva."}, {"id": "2-vulvovaginites-vaginose-tr-25", "topic": "2-vulvovaginites-vaginose-tr", "q": "Como é a clínica da candidíase?", "a": "Prurido que piora com calor, corrimento em leite talhado sem odor, ardor, dispareunia, disúria."}, {"id": "2-vulvovaginites-vaginose-tr-26", "topic": "2-vulvovaginites-vaginose-tr", "q": "Achado do KOH 10%?", "a": "Pseudo-hifas."}, {"id": "2-vulvovaginites-vaginose-tr-27", "topic": "2-vulvovaginites-vaginose-tr", "q": "Tratamento da não complicada (slide)?", "a": "Fluconazol 150 mg VO dose única ou azólico tópico."}, {"id": "2-vulvovaginites-vaginose-tr-28", "topic": "2-vulvovaginites-vaginose-tr", "q": "Definição e conduta na CVVR?", "a": "≥ 4 episódios/ano; cultura, 14 dias de tópico e fluconazol 150 mg semanal por 6 meses."}, {"id": "2-vulvovaginites-vaginose-tr-29", "topic": "2-vulvovaginites-vaginose-tr", "q": "Quando tratar o parceiro na candidíase?", "a": "Só com balanite ou dermatite peniana."}, {"id": "2-vulvovaginites-vaginose-tr-30", "topic": "2-vulvovaginites-vaginose-tr", "q": "Corrimento + pH 6,5 + disúria + colo em morango: diagnóstico e conduta?", "a": "Tricomoníase; metronidazol para paciente e parceiro."}, {"id": "2-vulvovaginites-vaginose-tr-31", "topic": "2-vulvovaginites-vaginose-tr", "q": "Prurido intenso sem odor + pseudo-hifas: diagnóstico?", "a": "Candidíase."}, {"id": "2-vulvovaginites-vaginose-tr-32", "topic": "2-vulvovaginites-vaginose-tr", "q": "Corrimento fino com odor, sem leucócitos, clue cells: diagnóstico?", "a": "Vaginose bacteriana."}, {"id": "2-vulvovaginites-vaginose-tr-33", "topic": "2-vulvovaginites-vaginose-tr", "q": "Corrimento com dor pélvica e dor à mobilização do colo: o que afastar?", "a": "DIP (não tratar como vaginite simples)."}, {"id": "3-fisiologia-do-ciclo-menstr-01", "topic": "3-fisiologia-do-ciclo-menstr", "q": "O que é polimenorreia e oligomenorreia?", "a": "Ciclos &lt; 24 dias e &gt; 35 dias, respectivamente."}, {"id": "3-fisiologia-do-ciclo-menstr-02", "topic": "3-fisiologia-do-ciclo-menstr", "q": "Na Aula 3, o que é hipermenorreia e o que é menorragia?", "a": "Hipermenorreia = duração aumentada; menorragia = volume aumentado."}, {"id": "3-fisiologia-do-ciclo-menstr-03", "topic": "3-fisiologia-do-ciclo-menstr", "q": "Por que o sangue menstrual não coagula?", "a": "Não tem fibrinogênio e é fibrinolítico."}, {"id": "3-fisiologia-do-ciclo-menstr-04", "topic": "3-fisiologia-do-ciclo-menstr", "q": "Qual fase determina a duração do ciclo?", "a": "A folicular (a lútea é fixa em 14 dias)."}, {"id": "3-fisiologia-do-ciclo-menstr-05", "topic": "3-fisiologia-do-ciclo-menstr", "q": "Explique a teoria das duas células.", "a": "LH na teca produz androgênios; FSH na granulosa ativa a aromatase e converte em estradiol."}, {"id": "3-fisiologia-do-ciclo-menstr-06", "topic": "3-fisiologia-do-ciclo-menstr", "q": "Como são os pulsos de GnRH na fase folicular e na lútea?", "a": "Folicular: frequentes e de baixa amplitude. Lútea: menos frequentes e de maior amplitude."}, {"id": "3-fisiologia-do-ciclo-menstr-07", "topic": "3-fisiologia-do-ciclo-menstr", "q": "Qual o gatilho do pico de LH?", "a": "Estradiol alto e sustentado (~200 pg/mL por ~50 h) → feedback positivo."}, {"id": "3-fisiologia-do-ciclo-menstr-08", "topic": "3-fisiologia-do-ciclo-menstr", "q": "O que acontece com o folículo em microambiente androgênico?", "a": "Atresia."}, {"id": "3-fisiologia-do-ciclo-menstr-09", "topic": "3-fisiologia-do-ciclo-menstr", "q": "Quando há o número máximo de oócitos e quantos ovulam?", "a": "Às 16–20 semanas de gestação (~7 milhões); ~400 ovulam na vida."}, {"id": "3-fisiologia-do-ciclo-menstr-10", "topic": "3-fisiologia-do-ciclo-menstr", "q": "A pílula ou a gravidez \"poupam\" folículos?", "a": "Não. A atresia continua."}, {"id": "3-fisiologia-do-ciclo-menstr-11", "topic": "3-fisiologia-do-ciclo-menstr", "q": "Quanto tempo antes da ovulação ocorre o pico de LH?", "a": "~36 horas antes."}, {"id": "3-fisiologia-do-ciclo-menstr-12", "topic": "3-fisiologia-do-ciclo-menstr", "q": "Em que fase da meiose o oócito está na ovulação?", "a": "Metáfase II."}, {"id": "3-fisiologia-do-ciclo-menstr-13", "topic": "3-fisiologia-do-ciclo-menstr", "q": "Por que a libido aumenta no meio do ciclo?", "a": "O pico de LH aumenta os androgênios tecais."}, {"id": "3-fisiologia-do-ciclo-menstr-14", "topic": "3-fisiologia-do-ciclo-menstr", "q": "O que mantém o corpo lúteo na gravidez e até quando?", "a": "hCG, até ~8 semanas."}, {"id": "3-fisiologia-do-ciclo-menstr-15", "topic": "3-fisiologia-do-ciclo-menstr", "q": "Ciclo de 40 dias com fase lútea normal: o que está prolongado?", "a": "A fase folicular (lútea fixa em 14 dias)."}, {"id": "3-fisiologia-do-ciclo-menstr-16", "topic": "3-fisiologia-do-ciclo-menstr", "q": "Em que dia ovula uma mulher com ciclos de 35 dias?", "a": "Por volta do dia 21 (35 − 14)."}, {"id": "3-fisiologia-do-ciclo-menstr-17", "topic": "3-fisiologia-do-ciclo-menstr", "q": "FSH e LH altos com estrogênio baixo: qual compartimento?", "a": "II (ovário) — hipogonadismo hipergonadotrófico."}, {"id": "3-fisiologia-do-ciclo-menstr-18", "topic": "3-fisiologia-do-ciclo-menstr", "q": "FSH e LH baixos com estrogênio baixo: qual compartimento?", "a": "III ou IV (hipófise ou hipotálamo) — hipogonadotrófico."}, {"id": "3-fisiologia-do-ciclo-menstr-19", "topic": "3-fisiologia-do-ciclo-menstr", "q": "FSH aumentado com LH normal/baixo sugere o quê? [Complemento]", "a": "Reserva ovariana diminuída / transição menopausal inicial (queda da inibina B)."}, {"id": "3-fisiologia-do-ciclo-menstr-20", "topic": "3-fisiologia-do-ciclo-menstr", "q": "Lesão das células da teca com FSH normal: o que acontece com o estradiol?", "a": "Cai, por falta de substrato androgênico para a aromatase."}, {"id": "4-amenorreias-01", "topic": "4-amenorreias", "q": "Defina amenorreia primária e secundária (slide).", "a": "Primária: 13 anos sem caracteres ou 15 com caracteres. Secundária: 3 meses (regulares) ou 6 meses (irregulares)."}, {"id": "4-amenorreias-02", "topic": "4-amenorreias", "q": "Qual a causa mais comum de amenorreia e sua frequência?", "a": "Gravidez, ~70%."}, {"id": "4-amenorreias-03", "topic": "4-amenorreias", "q": "Liste os 4 compartimentos.", "a": "I útero/vagina; II ovário; III hipófise anterior; IV SNC/hipotálamo."}, {"id": "4-amenorreias-04", "topic": "4-amenorreias", "q": "Radioterapia e quimioterapia causam amenorreia em qual compartimento?", "a": "II (ovário)."}, {"id": "4-amenorreias-05", "topic": "4-amenorreias", "q": "Qual a sequência de investigação da amenorreia secundária?", "a": "Beta-hCG → TSH e PRL → teste da progesterona → teste E+P → FSH → (teste do GnRH / RNM)."}, {"id": "4-amenorreias-06", "topic": "4-amenorreias", "q": "Teste da progesterona positivo significa?", "a": "Endométrio estrogenizado e trato pérvio: anovulação crônica (ex.: SOP)."}, {"id": "4-amenorreias-07", "topic": "4-amenorreias", "q": "Teste E+P negativo indica?", "a": "Causa estrutural uterina (ex.: Asherman) → HSG ou histeroscopia."}, {"id": "4-amenorreias-08", "topic": "4-amenorreias", "q": "Teste E+P positivo exclui o quê?", "a": "Causas anatômicas (útero e vagina). Próximo passo: FSH."}, {"id": "4-amenorreias-09", "topic": "4-amenorreias", "q": "FSH alto após E+P positivo indica? E baixo?", "a": "Alto: compartimento II (ovário). Baixo: III ou IV (central)."}, {"id": "4-amenorreias-10", "topic": "4-amenorreias", "q": "Como o teste do GnRH diferencia hipotálamo de hipófise?", "a": "Se as gonadotrofinas sobem = hipotálamo; se não sobem = hipófise."}, {"id": "4-amenorreias-11", "topic": "4-amenorreias", "q": "Critérios de IOP do slide?", "a": "&lt; 40 anos com FSH &gt; 25 mUI/mL em duas dosagens."}, {"id": "4-amenorreias-12", "topic": "4-amenorreias", "q": "Prolactina acima de quanto sugere tumor e qual o tratamento?", "a": "&gt; 100; cabergolina ou bromocriptina."}, {"id": "4-amenorreias-13", "topic": "4-amenorreias", "q": "Tratamento do Asherman?", "a": "Lise das aderências por histeroscopia + DIU."}, {"id": "4-amenorreias-14", "topic": "4-amenorreias", "q": "Mamas e pelos normais, sem útero, 46,XX: diagnóstico?", "a": "MRKH."}, {"id": "4-amenorreias-15", "topic": "4-amenorreias", "q": "Mamas normais, sem pelos, 46,XY, hérnia inguinal: diagnóstico e conduta?", "a": "Morris (insensibilidade androgênica); gonadectomia + estrogênio."}, {"id": "4-amenorreias-16", "topic": "4-amenorreias", "q": "Amenorreia primária + anosmia: diagnóstico?", "a": "Kallmann."}, {"id": "4-amenorreias-17", "topic": "4-amenorreias", "q": "Por que Turner tem pubarca normal?", "a": "Os androgênios adrenais não dependem do ovário."}, {"id": "4-amenorreias-18", "topic": "4-amenorreias", "q": "Hemorragia no parto e não conseguiu amamentar: diagnóstico?", "a": "Sheehan."}, {"id": "4-amenorreias-19", "topic": "4-amenorreias", "q": "Curetagem prévia + E+P negativo: diagnóstico e exame?", "a": "Asherman; histeroscopia ou HSG."}, {"id": "4-amenorreias-20", "topic": "4-amenorreias", "q": "Corredora, IMC 18, FSH/LH baixos, PRL normal: diagnóstico?", "a": "Amenorreia hipotalâmica funcional."}, {"id": "4-amenorreias-21", "topic": "4-amenorreias", "q": "Mulher de 34 anos tratada com quimiorradiação para câncer de colo evolui com amenorreia: padrão hormonal e compartimento?", "a": "FSH e LH altos, estradiol baixo: insuficiência ovariana (compartimento II), causa citada no slide (irradiação pélvica/QT)."}, {"id": "4-amenorreias-22", "topic": "4-amenorreias", "q": "Amenorreia com dor cíclica após conização: mecanismo? [Complemento]", "a": "Estenose cervical com hematometra (compartimento I)."}, {"id": "5-abdome-agudo-ginecologico-01", "topic": "5-abdome-agudo-ginecologico", "q": "Quais são os agentes principais da DIP?", "a": "<i>Neisseria gonorrhoeae</i> e <i>Chlamydia trachomatis</i>."}, {"id": "5-abdome-agudo-ginecologico-02", "topic": "5-abdome-agudo-ginecologico", "q": "Descreva a sequência de ascensão da DIP.", "a": "Cervicite → endometrite → salpingite → ooforite/abscesso tubovariano → peritonite pélvica."}, {"id": "5-abdome-agudo-ginecologico-03", "topic": "5-abdome-agudo-ginecologico", "q": "Qual o momento típico de início da DIP?", "a": "Pós-menstrual, sem atraso menstrual."}, {"id": "5-abdome-agudo-ginecologico-04", "topic": "5-abdome-agudo-ginecologico", "q": "Em que porcentagem há febre na DIP?", "a": "Apenas 20 a 30%."}, {"id": "5-abdome-agudo-ginecologico-05", "topic": "5-abdome-agudo-ginecologico", "q": "Qual a taxa de erro do diagnóstico só clínico?", "a": "30%."}, {"id": "5-abdome-agudo-ginecologico-06", "topic": "5-abdome-agudo-ginecologico", "q": "Defina os 4 estádios de Monif.", "a": "1: endometrite/salpingite sem peritonite. 2: salpingite com peritonite. 3: oclusão tubária/abscesso íntegro. 4: abscesso roto."}, {"id": "5-abdome-agudo-ginecologico-07", "topic": "5-abdome-agudo-ginecologico", "q": "Monif 3: conduta? Monif 4: conduta?", "a": "3: internar, antibiótico, observar 48 h e operar se não melhorar. 4: cirurgia imediata."}, {"id": "5-abdome-agudo-ginecologico-08", "topic": "5-abdome-agudo-ginecologico", "q": "Cite 5 indicações de internação na DIP.", "a": "Dúvida diagnóstica, abscesso, gravidez, adolescência, má adesão, falha ambulatorial, doença grave, sem reavaliação."}, {"id": "5-abdome-agudo-ginecologico-09", "topic": "5-abdome-agudo-ginecologico", "q": "Quais as sequelas da DIP e suas frequências?", "a": "Esterilidade 12,5–25%; dor pélvica crônica/dispareunia 18%; ectópica; hidrossalpinge."}, {"id": "5-abdome-agudo-ginecologico-10", "topic": "5-abdome-agudo-ginecologico", "q": "\"Febre &gt; 38 °C raramente é cirúrgica\": qual a exceção na DIP?", "a": "Monif 4 (abscesso roto) é cirúrgico imediato."}, {"id": "5-abdome-agudo-ginecologico-11", "topic": "5-abdome-agudo-ginecologico", "q": "Qual a classificação sindrômica da DIP? E da torção?", "a": "DIP: inflamatória. Torção: vascular."}, {"id": "6-cancer-do-colo-uterino-e-l-01", "topic": "6-cancer-do-colo-uterino-e-l", "q": "Qual o fator principal de progressão do HPV ao câncer?", "a": "Persistência da infecção por HPV oncogênico."}, {"id": "6-cancer-do-colo-uterino-e-l-02", "topic": "6-cancer-do-colo-uterino-e-l", "q": "Em quanto tempo a maioria das infecções regride?", "a": "Até 24 meses."}, {"id": "6-cancer-do-colo-uterino-e-l-03", "topic": "6-cancer-do-colo-uterino-e-l", "q": "HPV 6 e 11 causam o quê? E 16 e 18?", "a": "6/11: condilomas (baixo risco). 16/18: alto risco — 16 escamoso, 18 adenocarcinoma."}, {"id": "6-cancer-do-colo-uterino-e-l-04", "topic": "6-cancer-do-colo-uterino-e-l", "q": "Menarca precoce é fator de risco para câncer de colo?", "a": "Não (pegadinha de prova). Multiparidade é."}, {"id": "6-cancer-do-colo-uterino-e-l-05", "topic": "6-cancer-do-colo-uterino-e-l", "q": "Qual região do colo concentra as lesões?", "a": "Zona de transformação (junção escamocolunar, metaplasia escamosa)."}, {"id": "6-cancer-do-colo-uterino-e-l-06", "topic": "6-cancer-do-colo-uterino-e-l", "q": "Esquema da vacina HPV para 9 a 14 anos no SUS?", "a": "Dose única."}, {"id": "6-cancer-do-colo-uterino-e-l-07", "topic": "6-cancer-do-colo-uterino-e-l", "q": "Menina de 12 anos vítima de violência sexual: esquema?", "a": "2 doses (0 e 6 meses)."}, {"id": "6-cancer-do-colo-uterino-e-l-08", "topic": "6-cancer-do-colo-uterino-e-l", "q": "Mulher de 29 anos tratada por conização por NIC 3: vacina?", "a": "Sim, independente da idade, 3 doses (0-2-6), até 12 meses após o procedimento."}, {"id": "6-cancer-do-colo-uterino-e-l-09", "topic": "6-cancer-do-colo-uterino-e-l", "q": "Imunossuprimida de 30 anos: esquema?", "a": "3 doses (0-2-6)."}, {"id": "6-cancer-do-colo-uterino-e-l-10", "topic": "6-cancer-do-colo-uterino-e-l", "q": "Rastreamento citológico: início, periodicidade e fim?", "a": "25 anos; 2 anuais e depois a cada 3 anos; até 64 anos."}, {"id": "6-cancer-do-colo-uterino-e-l-11", "topic": "6-cancer-do-colo-uterino-e-l", "q": "ASC-US em mulher de 27 anos? E de 32?", "a": "27: repetir em 12 meses. 32: repetir em 6 meses."}, {"id": "6-cancer-do-colo-uterino-e-l-12", "topic": "6-cancer-do-colo-uterino-e-l", "q": "LSIL em mulher de 23 anos?", "a": "Repetir citologia em 3 anos."}, {"id": "6-cancer-do-colo-uterino-e-l-13", "topic": "6-cancer-do-colo-uterino-e-l", "q": "ASC-H e HSIL: conduta?", "a": "Colposcopia."}, {"id": "6-cancer-do-colo-uterino-e-l-14", "topic": "6-cancer-do-colo-uterino-e-l", "q": "DNA-HPV positivo para HPV 16: conduta?", "a": "Colposcopia direto (sem citologia antes)."}, {"id": "6-cancer-do-colo-uterino-e-l-15", "topic": "6-cancer-do-colo-uterino-e-l", "q": "DNA-HPV positivo para HPV 51 (não 16/18): conduta?", "a": "Citologia reflexa; se ASC-US+ colposcopia, se normal repetir em 1 ano."}, {"id": "6-cancer-do-colo-uterino-e-l-16", "topic": "6-cancer-do-colo-uterino-e-l", "q": "DNA-HPV negativo: quando repetir na imunocompetente e na HIV?", "a": "5 anos e 3 anos."}, {"id": "6-cancer-do-colo-uterino-e-l-17", "topic": "6-cancer-do-colo-uterino-e-l", "q": "Mulher de 61 anos com DNA-HPV negativo?", "a": "Liberada do rastreamento (o próximo ultrapassaria 64 anos)."}, {"id": "6-cancer-do-colo-uterino-e-l-18", "topic": "6-cancer-do-colo-uterino-e-l", "q": "Qual o tipo histológico mais comum e qual HPV se associa a ele? E o adenocarcinoma?", "a": "Escamoso (~80%), HPV 16. Adenocarcinoma (~15%), HPV 18."}, {"id": "6-cancer-do-colo-uterino-e-l-19", "topic": "6-cancer-do-colo-uterino-e-l", "q": "Qual o sintoma clássico do câncer de colo?", "a": "Sangramento pós-coital (sinusiorragia)."}, {"id": "6-cancer-do-colo-uterino-e-l-20", "topic": "6-cancer-do-colo-uterino-e-l", "q": "Teste de Schiller iodo-negativo confirma câncer?", "a": "Não; a biópsia confirma."}, {"id": "6-cancer-do-colo-uterino-e-l-21", "topic": "6-cancer-do-colo-uterino-e-l", "q": "Lesão vegetante e friável no colo: conduta?", "a": "Coletar o CP e biopsiar a lesão."}, {"id": "6-cancer-do-colo-uterino-e-l-22", "topic": "6-cancer-do-colo-uterino-e-l", "q": "Invasão de 8 mm, tumor de 3 cm restrito ao colo: estádio?", "a": "IB2."}, {"id": "6-cancer-do-colo-uterino-e-l-23", "topic": "6-cancer-do-colo-uterino-e-l", "q": "Paramétrio acometido: estádio?", "a": "IIB."}, {"id": "6-cancer-do-colo-uterino-e-l-24", "topic": "6-cancer-do-colo-uterino-e-l", "q": "Hidronefrose por invasão da parede pélvica: estádio?", "a": "IIIB."}, {"id": "6-cancer-do-colo-uterino-e-l-25", "topic": "6-cancer-do-colo-uterino-e-l", "q": "Linfonodo para-aórtico: estádio? Metástase pulmonar?", "a": "IIIC2; IVB."}, {"id": "6-cancer-do-colo-uterino-e-l-26", "topic": "6-cancer-do-colo-uterino-e-l", "q": "Até qual estádio o tratamento é cirúrgico? A partir de qual é RT+QT?", "a": "Cirúrgico até IB2; RT+QT a partir de IB3."}, {"id": "6-cancer-do-colo-uterino-e-l-27", "topic": "6-cancer-do-colo-uterino-e-l", "q": "Mulher de 33 anos com câncer inicial que quer engravidar: opção?", "a": "Conização (IA1) ou traquelectomia radical (IA1–IB1)."}, {"id": "6-cancer-do-colo-uterino-e-l-28", "topic": "6-cancer-do-colo-uterino-e-l", "q": "Mulher de 48 anos, prole completa, IA1: tratamento?", "a": "Histerectomia total."}, {"id": "7-neoplasias-do-corpo-uterin-01", "topic": "7-neoplasias-do-corpo-uterin", "q": "Qual a frequência do mioma e com que frequência é múltiplo?", "a": "20–30% das mulheres (40–50% após 40 anos); múltiplo em ~84%."}, {"id": "7-neoplasias-do-corpo-uterin-02", "topic": "7-neoplasias-do-corpo-uterin", "q": "Por que o mioma regride na menopausa?", "a": "É hormônio-dependente (receptores de estrogênio e progesterona)."}, {"id": "7-neoplasias-do-corpo-uterin-03", "topic": "7-neoplasias-do-corpo-uterin", "q": "Mioma que cresce na pós-menopausa sugere o quê?", "a": "Malignidade (sarcoma) — indicação de tratamento invasivo."}, {"id": "7-neoplasias-do-corpo-uterin-04", "topic": "7-neoplasias-do-corpo-uterin", "q": "Qual a degeneração mais comum? E a típica da gravidez?", "a": "Hialina; vermelha (carnosa)."}, {"id": "7-neoplasias-do-corpo-uterin-05", "topic": "7-neoplasias-do-corpo-uterin", "q": "Qual a frequência da degeneração sarcomatosa?", "a": "0,07 a 0,5%."}, {"id": "7-neoplasias-do-corpo-uterin-06", "topic": "7-neoplasias-do-corpo-uterin", "q": "Qual o método de escolha para diagnosticar mioma?", "a": "Ultrassonografia."}, {"id": "7-neoplasias-do-corpo-uterin-07", "topic": "7-neoplasias-do-corpo-uterin", "q": "Qual mioma causa mais sangramento e infertilidade?", "a": "Submucoso."}, {"id": "7-neoplasias-do-corpo-uterin-08", "topic": "7-neoplasias-do-corpo-uterin", "q": "O que é a síndrome de Meigs?", "a": "Tumor benigno de ovário (fibroma) com ascite e derrame pleural."}, {"id": "7-neoplasias-do-corpo-uterin-09", "topic": "7-neoplasias-do-corpo-uterin", "q": "Por quanto tempo pode-se usar análogo de GnRH e por quê?", "a": "No máximo 6 meses, pelo risco de osteoporose (menopausa química)."}, {"id": "7-neoplasias-do-corpo-uterin-10", "topic": "7-neoplasias-do-corpo-uterin", "q": "Cite as indicações de tratamento invasivo do mioma.", "a": "SUA refratário, anemia, suspeita de malignidade, crescimento pós-menopausa, dor/compressão, infertilidade."}, {"id": "7-neoplasias-do-corpo-uterin-11", "topic": "7-neoplasias-do-corpo-uterin", "q": "Mioma submucoso com desejo de gestar: conduta?", "a": "Miomectomia histeroscópica."}, {"id": "7-neoplasias-do-corpo-uterin-12", "topic": "7-neoplasias-do-corpo-uterin", "q": "Limite da miomectomia laparoscópica no slide?", "a": "Miomas &lt; 5 cm, até 5 miomas."}, {"id": "7-neoplasias-do-corpo-uterin-13", "topic": "7-neoplasias-do-corpo-uterin", "q": "Qual o risco da embolização?", "a": "Isquemia ovariana com menopausa precoce."}, {"id": "7-neoplasias-do-corpo-uterin-14", "topic": "7-neoplasias-do-corpo-uterin", "q": "Gestante com dor aguda sobre mioma conhecido: hipótese?", "a": "Degeneração vermelha."}, {"id": "7-neoplasias-do-corpo-uterin-15", "topic": "7-neoplasias-do-corpo-uterin", "q": "Tríade da adenomiose?", "a": "SUA, dismenorreia progressiva e útero aumentado."}, {"id": "7-neoplasias-do-corpo-uterin-16", "topic": "7-neoplasias-do-corpo-uterin", "q": "Mecanismo comum dos fatores de risco do câncer de endométrio?", "a": "Estrogênio sem oposição de progesterona."}, {"id": "8-mastologia-01", "topic": "8-mastologia", "q": "Por que a nuliparidade aumenta o risco de câncer de mama (aula)?", "a": "A mama só amadurece após a primeira gestação a termo; células ductais imaturas são menos resistentes."}, {"id": "8-mastologia-02", "topic": "8-mastologia", "q": "Tratamento da mastalgia intensa segundo a aula?", "a": "Tamoxifeno."}, {"id": "8-mastologia-03", "topic": "8-mastologia", "q": "Descarga láctea bilateral em uso de antipsicótico: conduta?", "a": "Dosar prolactina e TSH, pesquisar medicamentos (sem suspender automaticamente)."}, {"id": "8-mastologia-04", "topic": "8-mastologia", "q": "Quando pedir mamografia na descarga ceroláctea?", "a": "Só se &gt; 50 anos e nunca fez."}, {"id": "8-mastologia-05", "topic": "8-mastologia", "q": "Descarga sanguinolenta unilateral: causa provável e conduta?", "a": "Papiloma intraductal; encaminhar ao mastologista para biópsia."}, {"id": "8-mastologia-06", "topic": "8-mastologia", "q": "Puérpera com febre, dor e abaulamento mamário: conduta?", "a": "Compressa fria e esvaziamento da mama; manter a amamentação."}, {"id": "8-mastologia-07", "topic": "8-mastologia", "q": "Diabética com abscesso mamário: conduta?", "a": "Antibiótico (cefalexina/amoxicilina/clindamicina), drenagem do abscesso e controle do diabetes."}, {"id": "8-mastologia-08", "topic": "8-mastologia", "q": "Mastite do tabagista: onde ocorre e o que pode exigir?", "a": "Seios lactíferos (subareolar recidivante); pode exigir amputação de papila."}, {"id": "8-mastologia-09", "topic": "8-mastologia", "q": "Compressa quente trata abscesso mamário?", "a": "Não; é preciso drenar."}, {"id": "8-mastologia-10", "topic": "8-mastologia", "q": "Prurido mamilar unilateral aos 50 anos: conduta?", "a": "Corticoide tópico 30 dias; sem melhora, biópsia (Paget)."}, {"id": "8-mastologia-11", "topic": "8-mastologia", "q": "BI-RADS 3: características e conduta (slide)?", "a": "Margens circunscritas, eixo paralelo à pele; controle semestral."}, {"id": "8-mastologia-12", "topic": "8-mastologia", "q": "Diferencie PAAF, core e mamotomia.", "a": "PAAF: células soltas. Core: fragmento tecidual. Mamotomia: tecido e microcalcificações."}, {"id": "8-mastologia-13", "topic": "8-mastologia", "q": "PAAF que não aspira nada sugere?", "a": "Nódulo sólido."}, {"id": "8-mastologia-14", "topic": "8-mastologia", "q": "Sítios de metástase do câncer de mama?", "a": "Osso, fígado, pulmão e cérebro."}, {"id": "8-mastologia-15", "topic": "8-mastologia", "q": "Cite os 4 subtipos moleculares.", "a": "Luminal A, luminal B, HER2 e triplo negativo."}, {"id": "8-mastologia-16", "topic": "8-mastologia", "q": "Suspeita de prótese rota: exame? E seroma tardio?", "a": "RNM sem contraste; linfoma anaplásico de grandes células."}, {"id": "revisao-final-misturada-01", "topic": "revisao-final-misturada", "q": "Gestante com corrimento fino, odor de peixe e clue cells: tratamento do slide?", "a": "Metronidazol 250 mg VO 8/8 h por 7 dias."}, {"id": "revisao-final-misturada-02", "topic": "revisao-final-misturada", "q": "Corrimento espumoso + colo em morango: quem tratar?", "a": "Paciente e parceiro (metronidazol)."}, {"id": "revisao-final-misturada-03", "topic": "revisao-final-misturada", "q": "5 episódios de candidíase em 1 ano: conduta?", "a": "Cultura, tópico 14 dias e fluconazol 150 mg semanal por 6 meses."}, {"id": "revisao-final-misturada-04", "topic": "revisao-final-misturada", "q": "Abscesso tubovariano íntegro: Monif e conduta?", "a": "Monif 3; internar, observar 48 h, cirurgia se não melhorar."}, {"id": "revisao-final-misturada-05", "topic": "revisao-final-misturada", "q": "DNA-HPV positivo para HPV 18: conduta?", "a": "Colposcopia."}, {"id": "revisao-final-misturada-06", "topic": "revisao-final-misturada", "q": "Tumor de colo de 5 cm restrito ao colo: estádio e tratamento?", "a": "IB3; radioterapia + quimioterapia."}, {"id": "revisao-final-misturada-07", "topic": "revisao-final-misturada", "q": "Tratada por quimiorradiação de colo, amenorreia: FSH esperado?", "a": "Alto (&gt; 25 em duas dosagens) — insuficiência ovariana, compartimento II."}, {"id": "revisao-final-misturada-08", "topic": "revisao-final-misturada", "q": "Teste da progesterona positivo: diagnóstico?", "a": "Anovulação crônica (ex.: SOP)."}, {"id": "revisao-final-misturada-09", "topic": "revisao-final-misturada", "q": "FSH e LH baixos, estradiol baixo, PRL normal: compartimento?", "a": "III ou IV (central)."}, {"id": "revisao-final-misturada-10", "topic": "revisao-final-misturada", "q": "Pico de LH em relação à ovulação?", "a": "~36 h antes."}, {"id": "revisao-final-misturada-11", "topic": "revisao-final-misturada", "q": "Mioma com crescimento após a menopausa: o que fazer?", "a": "Tratamento invasivo — suspeita de malignidade."}, {"id": "revisao-final-misturada-12", "topic": "revisao-final-misturada", "q": "Degeneração mais comum do mioma?", "a": "Hialina."}, {"id": "revisao-final-misturada-13", "topic": "revisao-final-misturada", "q": "Descarga sanguinolenta unilateral: conduta?", "a": "Encaminhar ao mastologista para biópsia (papiloma provável)."}, {"id": "revisao-final-misturada-14", "topic": "revisao-final-misturada", "q": "BI-RADS 3: conduta?", "a": "Controle semestral."}, {"id": "revisao-final-misturada-15", "topic": "revisao-final-misturada", "q": "Mastite puerperal: suspender amamentação?", "a": "Não."}, {"id": "revisao-final-misturada-16", "topic": "revisao-final-misturada", "q": "Fator que NÃO é de risco para câncer de colo: multiparidade ou menarca precoce?", "a": "Menarca precoce (multiparidade é fator de risco)."}]};
